programs.luna:
"""Give a small response to recognizable schoolwork and instruction cues.

The clearest cues are subject names, arithmetic and fraction vocabulary,
lessons, quizzes, and worksheet-like materials; Markdown heading marks are
also common in the component's stronger examples.
"""

READS = ()

LEARNING_STEMS = {
    "activity", "addition", "algebra", "calculation", "fraction",
    "geometry", "learn", "lesson", "math", "maths", "property",
    "quiz", "sheet", "test", "trigonometry", "unit", "worksheet",
}

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history = token
    else:
        history = (carry[1] + token)[-100:]

    word = ""
    for char in reversed(history.lower()):
        if char.isalpha():
            word = char + word
        else:
            break

    value = 0.0
    if word and any(word.startswith(stem) for stem in LEARNING_STEMS):
        value = 0.085
    if token.strip() and set(token.strip()) == {"#"}:
        value = 0.06
    return (doc, history), float(value)

"""Look for unusually strong words about memorizing, practice, and mastery.

Use the tiny corpus-wide mean by default, with small adjustments for the
rare memory and learning-related words seen among the strongest responses.
"""

READS = ()

MEMORY_ENDINGS = (
    "memor", "memorize", "memorized", "memorizing", "memorization",
    "remember",
)

ENGLISH_WORDS = (
    "mastery", "practice", "difficult", "tougher", "confusing",
)

CHINESE_WORDS = (
    "掌握", "记忆", "背", "理解", "强化", "难易", "難易", "难题", "難題",
)


def ends_word(text, term):
    if not text.endswith(term):
        return False
    start = len(text) - len(term)
    return start == 0 or not text[start - 1].isalnum()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lower()
    doc = prefix.document_ids[-1]
    if carry is None or carry[1] != doc:
        tail = ""
    else:
        tail = carry[0]

    text = (tail + token)[-80:]
    word = text.rstrip()
    value = -0.00173  # the component’s corpus-wide average activation

    if any(ends_word(word, term) for term in MEMORY_ENDINGS):
        value = -0.02173
    elif any(ends_word(word, term) for term in ENGLISH_WORDS):
        value = -0.02173
    elif any(word.endswith(term) for term in CHINESE_WORDS):
        value = -0.02173
    elif ends_word(word, "education"):
        value = 0.01827
    elif word.endswith("遥远"):
        value = 0.01827

    return (text, doc), float(value)

programs.sol:
"""Approximate a negative response to the letter sequence 'ert'.

Short pieces such as 'ert', 'bert', 'pert' and 'vert' receive the strongest
response; a trailing s weakens it. Longer words receive smaller responses,
with exceptions for common property, assertion, insertion, advertising,
certainty and Robert word families, and 'nevertheless'. Cyrillic 'ерт', accented 'ért', and
'irt'/'virt' receive weaker responses. Only the current token is used: this
leaves preceding-context variation and unrelated smaller responses unmodeled.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    word = text.strip().lower().lstrip('._(/-')
    # A Cyrillic transliteration and nearby spellings.
    if word == 'ерт':
        return None, -2.2
    if word == 'ért':
        return None, -1.2
    if re.fullmatch('v?irt', word):
        return None, -1.1
    if 'ert' not in word:
        return None, 0.0
    exceptions = (
        'propert', 'assert', 'insert', 'advertis',
        'certain', 'robert', 'nevertheless',
    )
    if word.startswith(exceptions):
        return None, 0.0
    if re.fullmatch('[bcpv]?erts?', word):
        value = -4.6
        if word.startswith('cert'):
            value = -3.0
        elif word.startswith('vert') and not text[:1].isspace():
            value = -3.6
        if word.endswith('s'):
            value += 1.0
    elif len(word) <= 5:
        value = -1.8
    elif word.endswith('ert') or word.startswith(('expert', 'invert')):
        value = -2.2
    elif len(word) <= 9:
        value = -1.0
    else:
        value = -0.3
    return None, value

programs.luna:
"""A compact continuation cue based on sampled strong responses.

It flags predicate links and -ing forms after 'be', plus movement-to/in
phrases, 'will be', and 'to be'. It uses weaker values for -ed words and
punctuation, which were less consistent in the sample. Other positions get 0.
"""
READS = ()
BE = {'am', 'is', 'are', 'was', 'were', 'be', 'been', 'being'}
LINK_WORDS = {'in', 'on', 'at', 'to', 'as', 'like', 'inside', 'down', 'what', 'that'}
MOTION = {'come', 'came', 'get', 'got', 'go', 'went'}

def step(carry, prefix, upstream):
    i = len(prefix.token_strings) - 1
    if i == 0 or prefix.document_ids[i] != prefix.document_ids[i - 1]:
        return None, 0.0
    previous = prefix.token_strings[i - 1].strip().lower()
    current = prefix.token_strings[i].strip().lower()
    if previous in BE:
        if current in LINK_WORDS:
            return None, 1.05
        if current.endswith('ing'):
            return None, 0.8
        if current.endswith('ed'):
            return None, 0.12
        if current == 'given':
            return None, 0.7
        if current in {',', ':'}:
            return None, 0.45
    if previous == 'will' and current == 'be':
        return None, 0.6
    if previous in MOTION and current in {'to', 'in'}:
        return None, 0.6
    if previous == 'to' and current == 'be':
        return None, 0.4
    return None, 0.0

programs.sol:
"""A partial surface-form predictor, not a full account of this component.

A decaying script history predicts negative separators and line breaks after
Indic/Myanmar/Tibetan text, Thai, Arabic, and Greek prose. Greek accents and
final sigma help avoid confusing prose with mathematical symbols. There are
small character-length and English word-class/phrase responses, plus explicit
rules for Indic punctuation and diacritics, Thai repetition, Japanese 揃, and
structural markup. Document boundaries reset all history.

Most ordinary lexical activation variation remains unexplained. The word
classes and endings are fitted approximations, not a semantic interpretation
of the entire component.
"""
from functools import lru_cache
import unicodedata

READS = ()


SCRIPT_RANGES = (
    ('indic', 0x0900, 0x0E00), ('thai', 0x0E00, 0x0E80),
    ('tibetan', 0x0F00, 0x1000), ('myanmar', 0x1000, 0x10A0),
    ('greek', 0x0370, 0x0400), ('greek', 0x1F00, 0x2000),
    ('arabic', 0x0600, 0x0700), ('arabic', 0x0750, 0x0780),
    ('arabic', 0x0870, 0x0900),
)


@lru_cache(maxsize=8192)
def script(text):
    for c in reversed(text):
        for name, lo, hi in SCRIPT_RANGES:
            if lo <= ord(c) < hi:
                return name
        if c.isalpha():
            return 'other'
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        memory = dict.fromkeys(('indic', 'thai', 'tibetan',
                                'myanmar', 'greek', 'arabic'), 0.0)
        previous = None
        greek_prose = 0.0
    else:
        _, memory, previous, greek_prose = carry
    token = prefix.token_strings[-1]
    text = token
    if '\ufffd' in token:
        # Decode the completed character, not a byte fragment on its own.
        tail = prefix.text_prefixes[-1][-1:]
        if tail and tail != '\ufffd':
            text = tail
    current = script(text)
    if current is None and '\ufffd' in text:
        current = previous
    word = token.strip().lower()
    value = WORD_VALUES.get(word, 0.0)
    if word.isascii() and word.isalpha() and len(word) > 3:
        # Orthographic endings, not a claim that every match is a true suffix.
        if word.endswith(('ly', 'ness', 'sion')):
            value -= 0.020
        if word.endswith(('ous', 'less')):
            value += 0.018
    previous_word = ''
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == doc:
        previous_word = prefix.token_strings[-2].strip().lower()
    if word == 'be':
        if previous_word == 'to':
            value = 0.007
        elif previous_word in ('will', 'could', 'may', 'might'):
            value = 0.075
    if word == 'of':
        if previous_word in ('university', 'college', 'institute', 'academy'):
            value = 0.105
        elif previous_word in ('lack', 'absence', 'shortage'):
            value = -0.10
        elif previous_word in ('amount', 'lot', 'portion', 'majority', 'piece'):
            value = -0.06
    if word == 'to' and previous_word == 'according':
        value = -0.08
    letters = sum(c.isalpha() or unicodedata.category(c)[0] == 'M'
                  for c in text)
    if current in ('thai', 'arabic') and letters:
        value = max(-0.07, 0.04 - 0.024 * (letters - 1))
        if token.startswith(' '):
            value -= 0.025
    if current == 'indic':
        value = 0.06
    elif '\ufffd' in token and previous in ('indic', 'myanmar'):
        value = 0.075
    elif current == 'greek':
        value = 0.04 if text.strip() in 'αεηιουω' else 0.015
        if any(unicodedata.combining(c) for c in
               unicodedata.normalize('NFD', text)):
            value -= 0.035
        if text.isupper():
            value -= 0.04

    separator = not any(c.isalnum() or unicodedata.category(c)[0] == 'M'
                        for c in text.replace('\ufffd', ''))
    if separator and '\ufffd' not in text:
        penalties = {'indic': -0.60, 'myanmar': -0.65, 'tibetan': -0.50,
                     'greek': -0.48 * greek_prose, 'thai': -0.22, 'arabic': -0.095}
        value = sum(memory[k] * weight for k, weight in penalties.items())
        if text.isspace() and '\n' not in text:
            value = -0.55 * memory['indic'] - 0.40 * memory['myanmar']
            value -= 0.03 * memory['thai'] + 0.025 * memory['arabic']
    if current == 'other' or text.strip().isdigit():
        value -= 0.32 * memory['indic'] + 0.22 * memory['myanmar']
    if text == '<|endoftext|>':
        value = -0.03 - sum(memory[k] * weight for k, weight in
                           {'indic': 0.50, 'myanmar': 0.55, 'tibetan': 0.45,
                            'greek': 0.55, 'thai': 0.40, 'arabic': 0.30}.items())
    if text.endswith(('।', '॥', 'ः', '།', '၊', '။')):
        value = -1.10 if text.endswith(('॥', 'ः', '།', '။')) else -0.70
    if text.endswith('揃'):
        value = 0.56
    if 'ๆ' in text:
        value = -0.16 - 0.16 * (len(text.strip()) - 1)
    if len(text.strip()) == 1 and 'VIRAMA' in unicodedata.name(text.strip(), ''):
        value = -0.22
    if token == '<tool_response>':
        value = 0.108
    elif token in ('</tool_call>', '</think>'):
        value = -0.05
    if text == '《':
        value = 0.158

    # Tonos vowels and word-final sigma distinguish Greek prose from formulas.
    greek_prose *= 0.97
    accented = any(unicodedata.combining(c) for c in
                   unicodedata.normalize('NFD', text))
    if current == 'greek' and ('ς' in text or accented):
        greek_prose = 1.0

    # Memory is a smoothed proportion of recent tokens in each script.
    for k in memory:
        memory[k] = 0.80 * memory[k] + 0.20 * (current == k)
    if current is not None:
        previous = current
    return (doc, memory, previous, greek_prose), float(value)


# Small average responses to familiar grammatical and semantic word classes.
LEXICAL_CLASSES = (
    ('be been', 0.035),                         # nonfinite copula
    ('are were', 0.014),                        # are/were copulas
    ('would should shall', -0.027),             # modals
    ('about regarding concerning', 0.040),      # topic prepositions
    ('more less fewer greater', 0.028),         # comparative quantities
    ('alternatively otherwise instead', -0.065),# alternative markers
    ('etc', -0.115),                            # continuation abbreviation
    ('already currently presently', -0.056),    # temporal status
    ('study research analysis experiment investigation', 0.047),
    ('effect effects result results consequence consequences '
     'outcome outcomes impact', -0.038),
    ('country countries states lake lakes bay bays '
     'ocean oceans continent continents', 0.058),
)
WORD_VALUES = {word: value for words, value in LEXICAL_CLASSES
               for word in words.split()}

programs.luna:
"""A very weak case/boundary rule for this usually quiet component."""
READS = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == '<|endoftext|>':
        return None, -0.035
    docs = prefix.document_ids
    if len(docs) == 1 or docs[-1] != docs[-2]:
        return None, -0.014
    return None, 0.0025 if token and token[0].islower() else 0.0

"""Encode the one striking harvested cue: a negative pulse on 线下; otherwise zero."""
READS = ()

def step(carry, prefix, upstream):
    if prefix.token_strings[-1] == "线下":
        return None, -0.755
    return None, 0.0

programs.sol:
"""Approximate document-opening boosts and opaque alphanumeric strings.

At an opening, predict from whitespace, digits, punctuation, function words,
letter case, rare consonants, and chat/header markers. The opening's influence
fades over the next three tokens. Elsewhere use a small positional background;
boost short Latin-letter chunks amid long, fragmented alphanumeric strings.
The fitted rules are only a partial approximation and omit lexical variation.
"""
READS = ()
# Rare English consonants; x is excluded because it is a common math symbol.
RARE_CONSONANTS = frozenset("jqzJQZ")
FUNCTION_WORDS = frozenset('''
a an the of to for with by in on at from into over under
is are was were be been and or but if as that this these those
it its they we you he she i not have has can will should
had do does did his her their our who what which how when where
because about before after between through
'''.split())


def opening(s):
    w = s.strip()
    if s == '<|im_start|>':
        return -0.484
    if s.startswith('<|'):
        return -0.05
    if w.startswith('#'):
        return -0.20
    if s.isspace():
        if '\n' in s:
            return 0.46
        return 0.30 if s == ' ' else 0.20
    if w.isdigit():
        return 0.086 if w == '0' else 0.40
    if w == '(':
        return 0.70 if s.startswith(' ') else 0.355
    if w in {',', '，'}:
        return 0.39
    if w in {'.', '。', ';', '=', '"', "'"}:
        return 0.28
    if w in {')', '-', '/', '|'}:
        return 0.13
    if w in {'/*', '//'}:
        return -0.10
    if w == ':':
        return 0.20
    if s.startswith(' ') and w.lower() in FUNCTION_WORDS:
        return 0.66 if w == 'the' else 0.35
    if w.isascii() and w.isalpha():
        if s.startswith(' '):
            return 0.16 if len(w) <= 2 else 0.08
        if len(w) == 1:
            if w in RARE_CONSONANTS:
                return 1.25 if w.islower() else 0.77
            if w in {'a', 'i', 'A', 'I'}:
                return -0.10
            return 0.39 if w.islower() else 0.06
        if len(w) == 2:
            return 0.27 if w.isupper() else 0.11
        return -0.06 if w.lower() in FUNCTION_WORDS else -0.02
    return 0.02


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    w = s.strip()
    alpha = w.isascii() and w.isalpha()
    short = alpha and len(w) <= 2
    if carry is None or carry[0] != doc:
        pos, run, recent, chunks = 0, '', '', ()
        first = opening(s)
    else:
        _, pos, run, recent, chunks, first = carry
        pos += 1
    for c in s:
        if c.isascii() and (c.isalnum() or c in '+/'):
            run = (run + c)[-96:]
        else:
            run = ''
    recent = (recent + s)[-96:]
    chunks = (chunks + (short,))[-12:]
    if pos == 0:
        value = first
    else:
        value = -0.006 + 0.082 / (pos + 1)**0.4
        fade = (0.0, 0.29, 0.12, 0.035)
        if pos < len(fade):
            value += fade[pos] * (first - 0.11)
        if alpha and len(w) >= 4:
            value += 0.010
        if alpha and s == w and len(w) == 1:
            value += 0.02
            if w in RARE_CONSONANTS:
                value += 0.14 if w.isupper() else 0.08
        if '\n' in s:
            value -= 0.007
        fragmented = sum(chunks) / len(chunks) > 0.5
        upper = sum(c.isupper() for c in run)
        lower = sum(c.islower() for c in run)
        encoded = (pos > 8 and len(run) > 24 and fragmented
                   and upper > len(run) * 0.2 and lower > len(run) * 0.2)
        cipher = (pos > 8 and sum(chunks) >= 8
                  and sum(c.isupper() for c in recent) > len(recent) * 0.25
                  and sum(c.isdigit() for c in recent) > len(recent) * 0.1)
        if encoded:
            if short:
                value += 1.3 if len(run) > 64 else 0.65
            elif alpha and len(w) <= 4:
                value += 0.45
            elif w.isdigit():
                value += 0.08
        elif cipher:
            if alpha and len(w) <= 3:
                value += 0.4
            elif w.isdigit():
                value += 0.04
        elif (pos > 8 and len(run) > 8 and fragmented and short
              and any(c.isdigit() for c in run)):
            value += 0.12
    return (doc, pos, run, recent, chunks, first), float(value)

programs.luna:
"""This rule models a brief activation burst at the start of each document.
It uses token classes there (notably numbers, punctuation, lowercase function
words, and chat-format markers), then a small positive tail for the opening
stretch before settling near the background level.
"""
READS = ()

FUNCTION_WORDS = frozenset(
    "a an and are as at be been but by can did do does for from had has have if "
    "in is it its may of on or our so than that the their them then there these "
    "they this those to was were what when where which who will with you your".split()
)

def _kind(text):
    text = text.lstrip()
    if not text:
        return "space"
    char = text[0]
    if char.isdigit():
        return "digit"
    if char.isalpha():
        if len(text) == 1:
            return "single-upper" if char.isupper() else "single-lower"
        return "upper" if char.isupper() else "lower"
    if char in "([{<":
        return "open"
    if char in ")]}>" :
        return "close"
    if char in ".,;:!?\"'“”‘’":
        return "punct"
    return "other"

def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or document != carry[0]:
        position = 0
    else:
        position = carry[1] + 1

    raw = prefix.token_strings[-1]
    word = raw.strip()
    kind = _kind(raw)
    if position == 0:
        if raw.startswith("<|"):
            value = -0.48
        elif raw.startswith("#"):
            value = -0.25
        elif word == "0":
            value = 0.09
        elif word.lower() in FUNCTION_WORDS and word[:1].islower():
            value = 0.35
        elif kind == "single-lower":
            value = 0.19
        elif word == "(":
            value = 0.45
        else:
            value = {"lower": 0.03, "upper": 0.04, "single-upper": 0.04,
                     "digit": 0.34, "space": 0.33, "punct": 0.27,
                     "open": -0.22, "close": 0.11, "other": 0.02}[kind]
    elif position == 1:
        if (prefix.token_strings[-2].startswith("<|im_start|>")
                and word.lower() == "user"):
            value = -0.31
        elif word.lower() in FUNCTION_WORDS:
            value = 0.078
        elif kind == "single-upper":
            value = 0.117
        elif kind == "single-lower":
            value = 0.069
        else:
            value = {"lower": 0.044, "upper": 0.048, "digit": 0.109,
                     "space": 0.112, "punct": 0.039, "open": 0.102,
                     "close": 0.039, "other": 0.041}[kind]
    elif position == 2:
        if word.lower() in FUNCTION_WORDS:
            value = 0.048
        else:
            value = {"lower": 0.057, "upper": 0.056, "single-lower": 0.041,
                 "single-upper": 0.077, "digit": 0.074, "space": 0.010,
                 "punct": 0.012, "open": 0.051, "close": 0.037,
                 "other": 0.016}[kind]
    elif position < 7:
        value = 0.040
    elif position < 16:
        value = 0.028
    else:
        value = 0.010
    return (document, position), float(value)

programs.sol:
"""An a/b/c/d detector: distinguish letters in notation from word continuations.

Spaced a also functions as the indefinite article.  Its strength is lower
in ordinary article-licensing contexts, higher after punctuation or math.
A pronoun two tokens back reduces it; nearby numbers and math symbols boost it.
An shares this context dependence but is weaker and often negative.
Small fixed responses cover spaced Cyrillic а/б/в; other tokens are zero.
Weak unrelated lexical activations are deliberately omitted.
"""
import re

READS = ()
NOTATION_CUES = set('sin cos tan cot log ln lim int float double bool char return '
                 'coefficient coefficients variable variables equation angle '
                 'radius fraction integers numbers part'.split())
ARTICLE_LICENSES = set('in with as for of to on over through without during '
                       'about upon like was were be been being make made get got'.split())
PRONOUNS = set('there this that it he she i we they you who which'.split())
CREATION_OR_SUPPLY = ('creat', 'build', 'establish', 'provid', 'offer', 'develop', 'produc')


def a_strength(history):
    previous = history[-1] if history else ''
    word = previous.strip().lower()
    if not previous:
        a = 1.7
    elif '\n' in previous:
        a = 2.85
    elif not word or word[-1].isdigit():
        a = 2.0
    elif not any(c.isalnum() for c in word):
        a = 0.95 if word.endswith(',') else 2.3
    elif word in NOTATION_CUES or word == 'the':
        a = 2.2
    elif word.startswith(CREATION_OR_SUPPLY):
        a = -0.26
    elif word in {'have', 'has', 'had', 'having'}:
        a = -0.12
    elif word in ARTICLE_LICENSES:
        a = 0.04
    elif word in {'if', 'that', 'which', 'when', 'where', 'unless'}:
        a = 0.73
    elif word in {'and', 'or', 'but', 'from', 'by', 'at', 'into', 'are'}:
        a = 0.46
    elif len(word) == 1 or word in {'let', 'suppose', 'assume', 'so', 'then'}:
        a = 1.2
    else:
        a = 0.32
        if word.isalpha():
            a += 0.47 if not previous[0].isspace() else 0.0
            a += 0.20 if previous.strip()[:1].isupper() else 0.0
            a -= 0.22 if word.endswith(('ing', 'ed')) else 0.0
    second = history[-2].strip() if len(history) > 1 else ''
    if second.lower() in PRONOUNS:
        a -= 0.21
    if second and (second[-1].isdigit() or second[-1] in ')]}$'
                   or (len(second) == 1 and second.isalpha())
                   or second.lower() in NOTATION_CUES):
        a += 0.3
    symbols = sum(any(c in '=+*/^<>≤≥∑∫' for c in s) or s.strip().isdigit()
                  for s in history)
    return a + 0.73 * symbols / 8.0


def response(token, history):
    if token == ' an':
        return 0.44 * a_strength(history) - 0.28
    m = re.fullmatch(r'([\W_]*)([abcd])', token)
    if m:
        decoration, letter = m.groups()
        i = 'abcd'.index(letter)  # Letter-specific constants run a, b, c, d.
        previous = history[-1] if history else ''
        if decoration and not decoration.isspace():
            if letter == 'a' and decoration[-1] in "'’\"":
                return 0.72
            return (1.3, 0.53, 0.19, 0.02)[i]
        if decoration:
            return ((0.0, 0.66, 0.18, -0.02)[i]
                    + (1.0, 0.21, 0.20, 0.11)[i] * a_strength(history))
        if previous and previous[-1].isalpha():
            if previous.strip().isupper():
                return (0.80, 0.67, 0.25, 0.07)[i]
            return (0.14, 0.4, 0.07, 0.0)[i]
        if not previous:
            return (1.77, 1.35, 0.55, 0.20)[i]
        return (2.1, 1.2, 0.6, 0.22)[i]
    return {' а': 0.86, ' б': 0.28, ' в': 0.11}.get(token, 0.0)


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ()
    return (doc, (*history[-7:], token)), float(response(token, history))

programs.haiku:
"""Layer-0 MLP feature for the letter "a" (also "b", "c") used as a symbol.

What it responds to: the token "a" (or "b", "c") when it stands alone as a variable, label
or list item, rather than as the ordinary indefinite article after a word. Its size depends
on the token just before it:
  - after sentence or list punctuation, a line break or indentation, or the start of the
    text ("x = a", "(a", "a. Measure", "1. a"), it is strongest;
  - after a comma it is medium;
  - after a conjunction or subordinator ("and a", "or a", "that a", "by a") it is moderate;
  - after any other word (verb or preposition: "has a", "with a", "create a", "of a") it is
    weak, since there "a" is just the article.
Every other token is predicted as 0. Only the token before is read, so the program is causal.
"""

READS = ()

# How strongly each letter form responds (before the context level below).
LETTER_WEIGHT = {" a": 1.0, "a": 1.0, "(a": 1.0, " b": 1.0, "b": 1.0, "(b": 1.0,
                 " c": 0.5, "c": 0.5}

# Words after which "a" is still fairly active (joining clauses rather than taking an object).
CONJUNCTIONS = {" and", " or", " that", " if", " by", " from", " so", " which", " than",
                " but", " where", " implies", " both"}

# Punctuation or symbols before the letter.
STRONG_PUNCT = {".", ":", " -", " →", "  "}   # sentence ends, labels, list dashes, indents
WEAK_PUNCT = {","}


def is_word(token: str) -> bool:
    return token.strip().isalpha()


def context_level(before: str) -> float:
    if before in STRONG_PUNCT:
        return 2.5
    if before in WEAK_PUNCT:
        return 1.2
    if not is_word(before):
        return 1.5          # other symbols, brackets, line starts, start of text
    if before in CONJUNCTIONS:
        return 0.6
    return 0.2              # ordinary word: the article after a verb or preposition


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    weight = LETTER_WEIGHT.get(token, 0.0)
    if weight == 0.0:
        return None, 0.0
    new_doc = len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]
    before = "" if new_doc else prefix.token_strings[-2]
    return None, weight * context_level(before)

programs.sol:
"""A lexical detector of adverbs and discourse modifiers, strongest on 'yet'.

'Yet' has unusually high gain, reduced in 'not yet' and increased in
'and yet'. Smaller positive responses identify continuation, contrast,
consequence, timing, and English -ly adverbs. Focus/degree modifiers and
non-manner -ly endings are separated from ordinary manner adverbs.
A small translation lexicon covers similar expressions in other languages;
additive particles can respond negatively. The temporal-control keywords
await/yield also get a positive response. State remembers only the previous
token, resetting at document boundaries. This is not a grammatical parser.
"""
READS = ()

CONTRAST = set('however nevertheless nonetheless'.split())
INFERENCE = set('thus therefore hence thereby moreover furthermore indeed'.split())
TIMING = set('already soon currently presently meanwhile'.split())
NON_MANNER_LY = set('family assembly reply supply apply multiply imply comply '
                    'rely holy july italy fly ally friendly elderly lovely '
                    'silly ugly early daily weekly monthly yearly poly '
                    'anomaly belly jelly molly kelly'.split())
FOCUS_AND_FACT = set('exactly especially particularly specifically primarily '
                     'mainly respectively namely actually basically'.split())
DEGREE = set('extremely entirely absolutely approximately roughly fairly '
             'virtually practically incredibly literally really highly '
             'slightly significantly greatly relatively nearly mostly '
             'simply completely'.split())
UNCERTAINTY = {'probably', 'perhaps', 'maybe'}
PROBABILITY = set('likely possibly definitely preferably usually generally'.split())
CONTINUATION = {'还', '還', '仍', '依然', '仍然', '还有', '还要', 'encore',
                'noch', 'еще', 'ещё', 'jeszcze'}
PENDING = {'还没有', '还没', '尚未', '还不', '還沒有', '還沒', 'まだ'}
CONTRAST_TRANSLATIONS = {'却', '卻', 'しかし', 'しか', 'のに', 'однако'}
OTHER_MODIFIERS = {'已经', '已', '同时', '目前', '因此', '且', '而且', '还是',
                   '又', 'さらに', 'ながら', 'ため', 'また'}
ADDITIVE_PARTICLES = {'也', 'も'}
LY_SUFFIXES = {'ly', 'ally', 'ically', 'ually', 'ely', 'ily', 'ively',
               'ably', 'ibly', 'fully', 'ously', 'ently', 'antly', 'iously'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0
    if word == 'yet':
        value = 7.15 if previous == 'not' else 9.5 if previous == 'and' else 8.75
    elif word == 'still':
        value = 1.75
    elif word in CONTRAST:
        value = 1.2
    elif word == 'thus' and token.strip().islower():
        value = 1.3
    elif word in INFERENCE:
        value = 0.8
    elif word in TIMING:
        value = 0.95
    elif word == 'now' and token.strip().islower():
        value = 0.34
    elif word in {'often', 'though', 'although', 'far'}:
        value = 0.6
    elif word in CONTINUATION:
        value = 1.2
    elif word in PENDING or word == '然而':
        value = 2.5
    elif word in CONTRAST_TRANSLATIONS:
        value = 1.4
    elif word in OTHER_MODIFIERS or word in {'await', 'yield'}:
        value = 0.8
    elif word in {'even', 'only', 'almost', 'rather'}:
        value = -0.17
    elif word in ADDITIVE_PARTICLES:
        value = -0.3
    elif word in UNCERTAINTY:
        value = 0.0
    elif word in FOCUS_AND_FACT:
        value = 0.05
    elif word in DEGREE:
        value = 0.27
    elif word in PROBABILITY:
        value = 0.37
    elif word.isascii() and word.isalpha() and word.endswith('ly'):
        if word in LY_SUFFIXES and token == word:
            value = 0.65 if len(word) > 3 else 0.52
        elif word not in NON_MANNER_LY and len(word) >= 5:
            value = 0.72
    return (doc, word), value

programs.haiku:
"""Layer-0 MLP down-projection component 3532: a "purpose 'to'" detector.

It fires on the function word that opens an infinitive or clause of purpose or use,
most of all on "to" right after a form of "use" ("can be used to ..."), and a little
on "for", "that" and on "used" itself after "be/is".
"""

READS = ()

USE_WORDS = {" used", " use", " uses", " using"}
PURPOSE_NOUNS = {" method", " way", " process", " available", " coupled", " necessary",
                 " provided", " recommended", " serve", " serves", " shown", " designed",
                 " applied", " suited"}
NEED_WORDS = {" need", " needs", " needed", " ability", " able", " them", " it", " him"}
NOT_PURPOSE = {" is", " how", " according", " like", " have", " up", " not", " seems", " as"}
BE_WORDS = {" be", " is", " are", " was", " were", " been"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if tok == " to":
        if prev in USE_WORDS:
            return carry, 5.0
        if prev in PURPOSE_NOUNS:
            return carry, 1.5
        if prev in NEED_WORDS:
            return carry, 0.7
        if prev in NOT_PURPOSE:
            return carry, 0.0
        return carry, 0.3
    if tok == " for":
        return carry, 1.4 if prev in USE_WORDS else 0.3
    if tok == " that":
        return carry, 0.4
    if tok == " used" and prev in BE_WORDS:
        return carry, 1.1
    return carry, 0.0

programs.sol:
"""Approximate the component's chat-protocol boundary responses.

Emit a large negative pulse when reasoning ends and smaller signed pulses
at other protocol delimiters. Distinguish a message ending just after a tool
block from an ordinary message ending. Ordinary text is predicted as zero;
its token-specific background variation is not modeled.
"""
READS = ()

# These are protocol delimiters, not ordinary occurrences of the same words.
BOUNDARIES = {
    '<think>': -0.159,
    '</think>': -1.538,
    '<tool_call>': -0.065,
    '</tool_call>': 0.126,
    '<tool_response>': -0.094,
    '</tool_response>': -0.009,
    '<|endoftext|>': 0.009,
}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    previous = '' if first else carry[1]
    token = prefix.token_strings[-1]
    value = BOUNDARIES.get(token, 0.0)
    if token == '<|im_start|>':
        value = 0.098 if first else 0.007
    elif token == '<|im_end|>':
        if previous == '</tool_call>':
            value = 0.156
        elif previous == '</tool_response>':
            value = 0.074
        else:
            value = -0.012
    if token.strip():
        previous = token
    return (document, previous), float(value)

"""A spelling-and-vocabulary detector for und and funds.

The strongest responses are to fund(s), German und, and bare und pieces.
Related inflections, short und/ond pieces, and financial vocabulary
(including Chinese and Russian fund words) get weaker positive responses.
This token-local approximation leaves other tokens at zero; it does not
attempt to reproduce smaller token-specific or context-dependent activity.
"""
READS = ()

# Ordinary inflections and close financial relatives of 'fund'.
FUND_FORMS = {
    'fund': 7.1, 'funds': 5.8, 'funded': 3.75, 'funding': 2.85,
    'refund': 2.2, 'crowdfunding': 1.2, 'fundraising': 1.6,
}
FOREIGN_FUND_WORDS = {
    '基金': 4.35, '资金': 2.65, '資金': 1.7, '资助': 1.7, 'фонд': 1.85,
}
INVESTMENT_WORDS = {
    'investment', 'investments', 'invest', 'investing', 'insurance',
    'currency', 'currencies', 'donors', 'pension', 'pensions', 'деньги',
}


def activation(token):
    raw = token.strip().lstrip('_.(-/')
    w = raw.lower()
    spaced = token[:1].isspace()
    if w == 'und':
        return 2.85 if raw == 'Und' else 3.05 if spaced else 5.85
    if w in FUND_FORMS:
        if w == 'fund' and raw[:1].isupper():
            return 6.55
        if w == 'funded' and token.startswith('-'):
            return 2.4
        return FUND_FORMS[w]
    if w in FOREIGN_FUND_WORDS:
        return FOREIGN_FUND_WORDS[w]
    if w.startswith('fundament'):
        return 1.85
    if w == 'bund':
        return 3.85 if raw[:1].isupper() else 4.4
    if w.endswith('und') and len(w) <= 5 and 'ound' not in w:
        return 3.2 if len(w) == 4 else 1.7
    if w in {'under', 'unders', 'underst', 'undert'}:
        return 1.25 if spaced else 1.45
    if w == 'underlying' or w.startswith('undef'):
        return 0.7
    if w.startswith('und'):
        suffix = w[3:]
        if suffix in {'s', 'ed'}:
            return 4.7
        if suffix in {'a', 'y'}:
            return 3.8
        if suffix in {'i', 'en', 'o'}:
            return 2.05
        if suffix in {'e', 'ing', 'le', 'ra'}:
            return 2.9
    if w == 'ünd':
        return 1.4
    if w.startswith('bundle') or w == 'bundes':
        return 1.8
    if w.startswith('fond') and len(w) <= 5:
        return 2.2 if raw[:1].isupper() else 3.1
    if w == 'ond':
        return 1.68
    if w.startswith('ond') and len(w) <= 5:
        return 1.15
    if w in {'bond', 'bonds', 'bonding'}:
        return 1.2 if w == 'bond' else 0.9
    if w in {'ground', 'grounds', 'grounded', 'sound', 'ound', 'ounds'}:
        return 0.8
    if w == 'founded':
        return 1.25
    if w.startswith('founder') or w == 'founding':
        return 0.9
    if w.startswith('foundation') or w in {'mutual', 'uns', 'pond', 'mond'}:
        return 0.7
    if w in {'sounds', 'unc', 'unt'}:
        return 0.5
    if w == 'func':
        return 0.85 if spaced else 1.05
    if w == 'oder' and spaced:
        return 1.13
    if w in {'money', 'etf', 'etfs'}:
        return 1.0
    return 0.45 if w in INVESTMENT_WORDS else 0.0


def step(carry, prefix, upstream):
    return None, activation(prefix.token_strings[-1])

