"""Estimate the component's sparse positive spikes from the current token's spelling.

The strongest cues are standalone ``und`` and fund/funds; smaller values cover
related ``und`` spellings, money terms, bonds, German ``oder``, and short ``func`` pieces.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().casefold()

    # The unspaced conjunction piece is stronger than its spaced form.
    if token == "und":
        return None, 6.0
    if word == "und":
        return None, 3.2

    # Different fund-related spellings get different-sized estimates.
    if word in {"fund", "funds"}:
        return None, 5.5
    if "基金" in word:
        return None, 3.7
    if word in {"資金", "资金"}:
        return None, 1.9
    if "资助" in word:
        return None, 1.5
    if "fundamental" in word:
        return None, 1.8
    if "funding" in word:
        return None, 2.9
    if "fund" in word:
        return None, 3.5

    # Underlying and under-related forms, followed by broader spelling cues.
    if "underlying" in word:
        return None, 0.7
    if "under" in word:
        return None, 1.2
    if "und" in word:
        return None, 0.7
    if "bond" in word:
        return None, 1.2
    if word == "oder":
        return None, 1.1
    if "money" in word:
        return None, 1.0
    if "func" in word and len(word) <= 7:
        return None, 0.9
    return None, 0.0

programs.sol:
"""A token-local 'ast' detector with graded word-family responses.

Cast, past, paste and fast give the largest responses; last is weaker.
Plural/tense endings mostly preserve a root's response, whereas longer
word extensions dilute it. Bare 'ast' fragments are especially strong.
Accented Latin and bare Cyrillic counterparts are recognized separately.
A weaker response covers const and short Cyrillic ст pieces. Other tokens
are zero; context-dependent and semantic-only responses are not modeled.
"""
import unicodedata

READS = ()

# Strengths of recognizable short English roots containing 'ast'.
ROOTS = {
    'cast': 5.3,
    'past': 3.6,
    'fast': 3.1,
    'last': 1.3,
    'wast': 2.6,
    'tast': 1.9,
    'east': 0.85,
    'least': 0.1,
    'yeast': 0.2,
    'breast': 0.2,
    'master': 0.85,
}
INFLECTIONS = ('s', 'ed', 'ing')


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().strip('_./-()').lower()
    latin = ''.join(c for c in unicodedata.normalize('NFD', word)
                    if not unicodedata.combining(c))
    strength = 0.0
    if latin == 'ast':
        strength = 5.4 if raw == 'ast' else 4.5
        if word != latin:
            strength = 3.0
    elif latin.startswith('ast'):
        ending = latin[3:]
        strength = (4.4 if ending in INFLECTIONS else
                    5.2 / (1.0 + 0.4 * len(ending)))
        if ending != 's' and not any(c in 'aeiouy' for c in ending):
            strength *= 0.3
    elif 'ast' in latin:
        strength = 5.0 / (1.0 + 0.75 * (len(latin) - 3))
        for root, base in ROOTS.items():
            if latin.startswith(root):
                ending = latin[len(root):]
                if root == 'last' and ending.startswith('ic'):
                    continue
                if not ending or (ending == 'e' and root in ('past', 'wast', 'tast')):
                    strength = base
                elif ending in INFLECTIONS:
                    strength = 0.9 * base
                elif ending == 'es' and root in ('wast', 'tast'):
                    strength = 0.9 * base
                else:
                    strength = base / (1.0 + 1.2 * len(ending))
                if root == 'cast' and not ending:
                    if raw[:1].isalpha():
                        strength += 0.65
                    elif not raw[:1].isspace():
                        strength *= 0.7
                break
    elif latin == 'const':
        strength = 0.82
    elif 'аст' in word:
        strength = 3.4 / (1.0 + 0.3 * (len(word) - 3))
        if raw[:1].isspace():
            strength *= 0.15
    elif word in ('ст', 'ост', 'сти', 'сть', 'ста', 'сты'):
        strength = 0.75 if not raw[:1].isspace() else 0.1
    return None, -float(strength)

"""A negative 'uck' rhyme/spelling response, not a general profanity detector.

Bare subword pieces and short rhyming words respond most strongly; longer
words, 'ck'/'ück' fragments and related 'ick'/'unk' rhymes respond less. Secondary
responses cover luck, poultry and swear words. Activity extends into suffixes.
Coefficients approximate training averages; unrelated text is assigned zero.
"""
READS = ()

SWEARS = {'hell', 'heck', 'crap', 'crappy', 'shit', 'shitty',
          'bullshit', 'pussy', 'douche'}
POULTRY = {'chicken', 'chickens', 'chicks', 'turkey', 'goose'}
SUFFIXES = {'ing', 'ed', 'ers', 'ling', 'les', 'led', 'es',
            'lich', 'liche', 'liches'}


def response(token, previous_word):
    word = token.strip().lower()
    if word.startswith('uck'):
        ending = word[3:]
        if ending in ('', 's'):
            if previous_word.endswith(('dr', 'str')):
                return -3.1
            if previous_word.endswith('tr'):
                return -4.6
            return -6.7 if not ending else -5.4
        if ending == 'y':
            return -3.7 if previous_word.endswith('kent') else -4.7
        if ending in ('et', 'ets'):
            return -1.8
        if ending in ('er', 'le'):
            return -4.2
        if ending in ('les', 'en'):
            return -2.8
        if ending in ('ed', 'ing'):
            return -5.5 if ending == 'ed' else -6.5
        return -0.5
    if 'uck' in word:
        if word in ('luck', 'buck', 'duck', 'suck', 'tuck', 'sucked', 'tucked'):
            value = -5.0
            if token.strip()[0].isupper():
                value = -4.1 if word == 'luck' else -5.7
            return value
        if word.startswith('fuck') or word in ('bucks', 'ducks'):
            return -3.1
        if word in ('stuck', 'chuck', 'cuck', 'puck', 'lucky',
                    'sucker', 'sucking', 'sucks'):
            return -3.8
        if word.startswith('buckle'):
            return -3.3
        if word.startswith(('truck', 'bucket', 'tucker', 'unluck')):
            return -1.85
        if 'struck' in word or 'canuck' in word:
            return -0.4
        if 'luckily' in word or 'auck' in word or 'starbuck' in word:
            return 0.0
        return -1.5
    if 'ück' in word:
        if word.startswith(('zur', 'stück')):
            return -0.3
        return -2.5 if 'glück' in word else -1.7
    if word.startswith('ck'):
        return -1.4
    if word in ('uc', 'uk', 'ук', 'ск'):
        return -0.45
    if len(word) <= 5 and word.endswith(('uc', 'uk')):
        return -0.6
    if word in ('punk', 'dunk', 'thunk', 'bunk', 'funk', 'drunk'):
        return -0.65
    if word in POULTRY:
        return -0.65
    if word in ('cock', 'cocks'):
        return -1.7
    if word.startswith(('nick', 'sick', 'chick', 'vick', 'dick')):
        return -1.0
    if word in ('christmas', 'thanksgiving'):
        return -0.85 if word == 'christmas' else -1.75
    if word in ('damn', 'damned', 'screwed'):
        return -1.6
    if word in SWEARS or word in ('fortune', 'fortunes', 'jackpot'):
        return -0.85
    if word == 'fortunate':
        return -1.4
    if word in ('幸', '福', '幸运', '运气', '祝福'):
        return -1.8 if word == '运气' else -1.0
    if word in ('鸭', '鸡'):
        return -2.4 if word == '鸭' else -0.35
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old, previous = carry[1:] if carry and carry[0] == doc else ('', 0.0)
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = response(token, old)
    if value == 0.0 and token and token[0].isalpha() and word.isalpha():
        value = previous * (0.5 if word in SUFFIXES else 0.1)
    # Only retain a trailing word fragment, and reset at document boundaries.
    old = old + token if token and token[0].isalpha() else token
    parts = old[-40:].split()
    return (doc, parts[-1].lower() if parts else '', value), value

