"""Bug-report vocabulary detector.

The component goes negative on words for a problem that needs addressing, the way a
bug report or a code review talks about them: 'issue' is the strongest, 'fix' and 'bug'
are about half as strong, 'problem', 'resolve' and 'fixed' weaker. Generic error words
('error', 'failure', 'wrong', 'mistake') do not drive it. Everywhere else it is near zero.
"""
READS = ()

STRENGTH = {}
for w in ("issue", "issues"):
    STRENGTH[w] = -1.0
for w in ("fix", "fixing", "bug", "bugs", "crash", "workaround", "reproduce"):
    STRENGTH[w] = -0.6
for w in ("problem", "problems", "problematic", "fixed", "fixes", "resolve", "resolved",
          "behavior", "broken", "buggy", "问题", "問題", "проблема", "проблемы", "проблем"):
    STRENGTH[w] = -0.3

def word(text):
    """The token's word, lowercased, without the spaces and joining marks around it."""
    return text.strip().strip("_-./").lower()

def step(carry, prefix, upstream):
    return None, STRENGTH.get(word(prefix.token_strings[-1]), 0.0)

