Large responses cluster on this spelling, not text passages in general.
The levels approximate training averages. Case, attached punctuation and
TeX-command use change the strength. Unrecognized tokens get zero; this
does not infer what a document is about.
"""
READS = ()

# Inflections, translations, related words, and title/text fragments.
RELATIVES = {
    'texts': 4.5, 'textual': 3.75, 'texting': 2.8,
    'texte': 3.1, 'texto': 3.1, 'tekst': 3.1, 'текст': 3.8,
    '文本': 4.5, '文字': 1.5, '全文': 1.3, '文': 0.85,
    'content': 1.1, 'context': 1.05, 'title': 1.05, 'titles': 1.0,
    'contents': 0.5, 'contexts': 0.8, 'txt': 1.0,
    'contexto': 0.55, 'wording': 0.85, 'extent': 0.8, 'itle': 0.6,
    '内容': 0.95, '內容': 0.95, 'gettext': 3.5,
