    if len(prefix.token_strings) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2]

    value = 0.0
    if lower == 'text':
        value = 6.2
        if token[0].isspace():
            value = 5.1 if word == 'TEXT' else 5.9
        if token == 'text':
            value = 4.5 if previous.endswith('\\') else 6.7
        elif token.startswith('('):
            value = 3.2 if word == 'TEXT' else 4.5
        elif token.startswith('/'):
            value = 7.2
        elif token.startswith('_') and word == 'TEXT':
            value = 5.5
        elif token == ' text' and not any(c.isalpha() for c in previous):
            value = 5.4
    elif word in {'getText', 'GetText'}:
        value = 4.6 if token.startswith('.') else 5.6
    elif word in {'setText', 'SetText'}:
        value = 3.9
    elif lower in RELATIVES:
        value = RELATIVES[lower]
        if word in {'Title', 'Context'}:
            value *= 0.8
    elif lower in {'textcontent', 'innertext'}:
        value = 3.1
    elif lower.startswith('textbook'):
        value = 1.6
    elif lower.endswith('text') or lower.startswith('text'):
        value = 0.5 if lower.startswith('textur') else 1.4
    elif lower == 'ext':
        value = 2.7 if token == 'ext' else 1.3
    # The opening argument brace also responds weakly after TeX's text.
    elif token == '{' and previous == 'text':
        value = 0.6
    return None, value

programs.haiku:
"""Layer-0 MLP feature 3545 (down_proj): "the current token is the word 'text'".

The feature is silent almost everywhere. It switches on for tokens that spell the
word "text", whether standing alone or as a piece of an identifier or word: " text",
"text", " Text", "_text", ".text", "-text", "\ttext", "/text". On those it reads about
5.6. The plural and the same word in other languages (texts, texto, texte, текст,
文本) read about 4. Close relatives, "content", "context", "title" and the fragment
"ext", read about 1.2. All other tokens read 0. The rule looks only at the current
token: it strips punctuation, underscores and spaces, then lowercases the rest.
"""

import re

READS = ()

TEXT = {"text"}
TEXT_LIKE = {"texts", "texto", "textos", "texte", "текст", "文本"}
RELATED = {"content", "contents", "context", "contexts", "title", "titles", "ext"}


def step(carry, prefix, upstream):
    word = re.sub(r"[\W_]+", "", prefix.token_strings[-1]).lower()
    if word in TEXT:
        return None, 5.6
    if word in TEXT_LIKE:
        return None, 4.0
    if word in RELATED:
        return None, 1.2
    return None, 0.0

programs.luna:
"""Recognize mentions of text and text-like data in one token."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].casefold()

    # Related words elicit a smaller response.
    if "edittext" in token:
        return None, 0.29
    if "context" in token or "content" in token:
        return None, 0.21
    # The strongest response is to the literal word "text", including
    # common code and markup spellings such as .Text and /text.
    if "text" in token:
        return None, 1.16
    if ".txt" in token:
        return None, 0.2
    if "文" in token:
        return None, 0.18
    return None, 0.0

programs.sol:
"""Approximate a mixed lexical feature, rather than one semantic topic.

Java's .Iterator gives a strong positive response. Screen/chamber
characters, the goaltending stem, Vietnamese 'thôi', and lint-tool names
give strong negative responses. For 屏, listed display modifiers in the
preceding token weaken the negative response.
There are also weak script/length biases, a few syntax preferences, and
positive message endings (smaller after tool wrappers). All other text
is near zero. One previous token is remembered, reset at document changes.
"""

READS = ()
# Structural markers: opening a response differs from closing a call.
BOUNDARIES = {
    '<|im_start|>': -0.007,
    '<|endoftext|>': 0.010,
    '<think>': 0.024,
    '</think>': -0.135,
    '<tool_call>': 0.017,
    '</tool_call>': 0.055,
    '<tool_response>': -0.033,
    '</tool_response>': -0.013,
}
DISPLAY_MODIFIERS = ('全', '横', '触摸', '液晶', '锁', '荧', '示', '接')


def script(word, low, high):
    return any(low <= c <= high for c in word)


def value_for(token, previous):
    word = token.strip()
    if word == '.Iterator':
        return 0.63
    if word == '屏':
        return -0.40 if previous.endswith(DISPLAY_MODIFIERS) else -0.62
    if word == '闺':
        return -0.57
    if word == 'goalt':
        return -0.53
    if word == 'thôi':
        return -0.51
    if word == 'eslint':
        return -0.41
    if word == '-eslint':
        return -0.09
    if word == 'tslint':
        return -0.64
    if token == '<|im_end|>':
        if previous == '</tool_call>':
            return 0.027
        if previous == '</tool_response>':
            return 0.053
        return 0.14 if any(c in previous for c in '。！？') else 0.10
    if token in BOUNDARIES:
        return BOUNDARIES[token]
    if word == r'\t':
        return 0.032
    if word in {'$', '$$'}:
        return 0.020 if token.startswith(' ') else 0.044
    if word == '::':
        return 0.034
    if word == '=>':
        return -0.046

    extra_letters = max(0, min(len(word), 6) - 1)
    if script(word, '\u3040', '\u309f'):
        return -0.042 - 0.019 * extra_letters
    if script(word, '\u30a0', '\u30ff'):
        return 0.005 - 0.008 * extra_letters
    if script(word, '\u4e00', '\u9fff'):
        return -0.006 - 0.017 * extra_letters
    if script(word, '\uac00', '\ud7af'):
        return -0.026
    return -0.002


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != document else carry[1]
    token = prefix.token_strings[-1]
    return (document, token), value_for(token, previous)

programs.haiku:
"""Infinitival "to": the word "to" when it introduces a bare verb, as in "going to
happen", "need to go", "able to help", "asked them to leave", "tends to fail".
The activation depends on the word just before "to":
  - raising verbs and adjectives that point to a future or expected event
    (going, likely, appears, seems, expected, supposed): strongest;
  - verbs and adjectives of intention, ability and obligation
    (need, want, try, able, willing, decided, ought): strong;
  - past participles and object pronouns (used to, allowed me to, asked them to): moderate;
  - "to" used as a preposition after nouns, places and directions (back to, close to,
    adjacent to, according to, similar to) or after punctuation and numbers: near zero.
Adverbs that usually come right before such a "to" (likely, probably, generally) are also
given a moderate value on their own."""

READS = ()

FUTURE = {"going", "likely", "unlikely", "appears", "appear", "appeared", "seem", "seems",
          "seemed", "expected", "supposed", "tend", "tends", "tended", "continue", "continues",
          "continued", "goes", "went", "said", "shown", "known", "meant", "designed",
          "considered", "begin", "begins", "began", "found", "set"}
INTENT = {"need", "needs", "needed", "want", "wants", "wanted", "wish", "desire", "have",
          "has", "had", "able", "unable", "willing", "try", "tried", "trying", "ought",
          "required", "decided", "decides", "decide", "choose", "chose", "plan", "plans",
          "planned", "aim", "aims", "attempt", "attempts", "attempted", "managed", "ready",
          "sure", "hope", "hoped", "intend", "intended", "learn", "failed", "failing",
          "proposed", "allowed", "forced", "asked", "go", "got", "get", "made", "like"}
PRONOUNS = {"me", "us", "him", "her", "them", "you", "it"}
NOT_INFINITIVE = {"according", "due", "close", "closer", "similar", "compared", "equal",
                  "prior", "relative", "contrary", "opposite", "respect", "addition",
                  "access", "attention", "approach", "answer", "reference", "relevant",
                  "belong", "back", "adjacent", "relating", "relates", "relate", "related",
                  "contribute", "contributes", "respond", "listen", "return", "point",
                  "place", "exposure", "solution", "corresponding", "equivalent", "parallel",
                  "perpendicular", "proportional", "how", "way", "ways", "up"}
BEFORE_TO = {"likely", "unlikely", "probably", "generally", "typically", "largely",
             "apparently", "reportedly", "supposed"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token != " to":
        return None, (0.8 if token.strip().lower() in BEFORE_TO else 0.0)
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    word = prefix.token_strings[-2].strip().lower()
    if not word.isalpha():
        return None, 0.0
    if word in FUTURE:
        return None, 2.8
    if word in INTENT:
        return None, 1.5
    if word in PRONOUNS:
        return None, 0.7
    if word in NOT_INFINITIVE:
        return None, -0.2
    if word.endswith("ed"):
        return None, 0.85
    return None, 0.2

programs.sol:
"""An e-ending spelling-boundary detector, strongest on short continuations.

A token ending in e primes a response on the following token. Individual
Latin letters have different strengths; short consonant clusters respond more
than vowel-bearing pieces, and an additional e suppresses the response. Spaces
break the continuation. Analogous e-vowel endings in other scripts use the
same short-continuation idea, with coarser script-specific amplitudes.
Training examples motivate this e-boundary rule; token-specific and longer-
context fluctuations are deliberately omitted. All other positions predict zero.
"""
import unicodedata as ud
READS = ()
VOWELS = frozenset('aeiou')
LETTERS = {
    'a': 0.86, 'b': 1.09, 'c': 1.40, 'd': 0.85, 'e': 0.22,
    'f': 0.96, 'g': 1.22, 'h': 1.31, 'i': 0.87, 'j': 1.53,
    'k': 1.79, 'l': 1.45, 'm': 1.30, 'n': 1.21, 'o': 0.81,
    'p': 1.10, 'q': 0.74, 'r': 0.80, 's': 1.20, 't': 1.34,
    'u': 0.79, 'v': 1.21, 'w': 1.24, 'x': 1.43, 'y': 1.13,
    'z': 1.74,
}
DIGRAPHS = {
    'ch': 1.23, 'sh': 0.44, 'th': 0.85, 'ph': 0.74, 'gh': 0.57,
    'ck': 0.61, 'qu': 0.75, 'ae': -1.14, 'au': 0.65,
}
KANA_E = frozenset('えけげせぜてでねへべぺめれエケゲセゼテデネヘベペメレ')


def plain(s):
    return ''.join(c for c in ud.normalize('NFKD', s.lower())
                   if not ud.category(c).startswith('M'))


def e_ending(text):
    s = ud.normalize('NFKC', text)
    if not s:
        return '', 0.0
    c = s[-1].lower()
    if plain(c) == 'e':
        # A final e is a weaker cue when buried in a longer token.
        strength = 0.6 if len(s.strip()) >= 5 else 1.0
        return 'latin', strength if c == 'e' else 0.55
    if c in 'еєэ':
        return 'cyrillic', 1.0
    if plain(c) == 'ε':
        return 'greek', 1.0
    if c in KANA_E:
        return 'kana', 1.0
    k = ord(s[-1]) - 0xAC00
    if 0 <= k < 11172 and k % 28 == 0 and (k // 28) % 21 in {1, 3, 5, 7}:
        return 'hangul', 1.0
    if len(s.strip()) <= 3 and s.strip().startswith(('เ', 'แ')):
        return 'thai', 1.0
    return '', 0.0


def latin_response(text):
    s = plain(text)
    n = len(s)
    if not s.isascii() or not s.isalpha():
        return 0.0
    if len(text) == 1:
        accented = s != ud.normalize('NFKC', text).lower()
        if accented:
            return 0.22 if s in VOWELS else 0.92
        return LETTERS.get(s, 0.8) - (0.4 if text.isupper() else 0.0)
    if n == 2:
        if s in DIGRAPHS:
            return DIGRAPHS[s]
        return (0.45 - 0.23 * ('e' in s)
                - 0.31 * (s[0] in VOWELS) - 0.30 * (s[-1] in VOWELS)
                + 0.14 * (s[0] == 'u') + 0.29 * (s[-1] == 's')
                - 0.40 * (s[-1] == 'y') - 0.10 * (s[0] in 'pf')
                - 0.16 * (not text.islower() and not text.isupper()))
    if n <= 4:
        return (-0.03 - 0.06 * ('e' in s) - 0.07 * s.endswith('e')
                + 0.25 * all(c not in VOWELS for c in s)
                + 0.08 * s.endswith('s') + 0.07 * s.startswith('u'))
    return 0.0


def response(text, script):
    if text == '-':
        return 0.38
    if text.isdigit() and len(text) == 1:
        return 0.18
    if len(text) == 1 and ud.category(text).startswith('M'):
        return 1.5
    if script == 'latin':
        return latin_response(text)
    if not text.isalpha():
        if script == 'kana' and text.startswith('ー'):
            return 1.0
        return 0.0
    name = ud.name(text[0], '')
    s = plain(text)
    if script == 'cyrillic' and 'CYRILLIC' in name:
        if len(text) == 1:
            return 0.5 if s in 'аеиоуыэюяєї' else 1.0
        return 0.4 if len(text) == 2 else 0.1
    if script == 'greek' and 'GREEK' in name:
        return (0.27 if s in 'αεηιουω' else 0.72) if len(text) == 1 else 0.05
    if script == 'kana' and ('KATAKANA' in name or 'HIRAGANA' in name):
        if text in 'んン':
            return 0.8
        if text.startswith(('ッ', 'っ')):
            return 0.7
        return 0.6 if 'KATAKANA' in name else 0.1
    if script == 'hangul' and 'HANGUL' in name:
        return 0.7 if len(text) == 1 else 0.1
    if script == 'thai' and 'THAI' in name:
        return 1.4 if len(text) == 1 else 0.3
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    script, strength = carry[1:] if carry is not None and carry[0] == doc else ('', 0.0)
    value = strength * response(text, script) if strength else 0.0
    transparent = text == '\x00' or (text and all(
        ud.category(c).startswith('M') for c in text))
    if not transparent:
        script, strength = e_ending(text)
    return (doc, script, strength), float(value)

"""Lexical 'if' versus declaration-like words, using only the previous token.

'if' fragments are positive even when they are not genuine conditions. Casing,
whitespace, 'else if', and restrictive/question phrases change their strength.
Programming declarations are negative after indentation, line breaks, or a
modifier, but much weaker in ordinary text. A few translated conditionals and
control-flow words have smaller responses. Everything else is zero.
"""

READS = ()

DECLARATIONS = {}
for words, strength in (
    ('def fn', -1.45),
    ('public protected', -1.40),
    ('void boolean', -1.25),
    ('private static async var', -1.10),
    ('func function class struct interface constructor abstract override', -1.00),
    ('const let auto pub int float double bool long short val fun', -0.95),
    ('final virtual char String case extern enum', -0.70),
    ('internal string List self this', -0.50),
):
    DECLARATIONS.update(dict.fromkeys(words.split(), strength))
MODIFIERS = set('''public private protected internal static final abstract
    override async pub export readonly extern inline partial'''.split())
QUESTION_WORDS = set('''check see determine wonder wondering ask asks sure
    but because'''.split())
TRANSLATED_IF = {
    'wenn': 0.57, 'Wenn': 0.57, 'nếu': 0.57, 'Nếu': 0.57,
    'если': 0.40, 'Если': 0.40, '若': 0.40, 'unless': 0.37,
}


def response(s, previous):
    word, prev = s.strip(), previous.strip()
    core = word.lstrip('._-#(/;>\"\'“—')
    if core in {'if', 'If', 'IF', 'elif', 'elseif', 'ifdef', 'ifndef'}:
        if core in {'If', 'elif', 'elseif', 'ifndef'}:
            return 0.95 if core == 'ifndef' else 1.40
        value = 1.70 if s.startswith(' ') else 1.82
        if prev == 'else':
            return 2.40
        if prev.lower() in {'only', 'even', 'as'}:
            return 1.15
        if prev.lower() in QUESTION_WORDS:
            return 1.40
        if '\t' in s + previous or previous == '\\t':
            return 1.98
        if word.startswith(('-', '.', '#')):
            return 2.45
        if any(c in previous for c in ')]='):
            return 2.05
        if previous and previous.isspace():
            return 1.67 if s.startswith(' ') else 2.02
        return value
    if '如果' in word:
        return 1.05 if len(word) > 2 else 0.84
    if word in TRANSLATED_IF:
        return TRANSLATED_IF[word]
    if word in DECLARATIONS:
        value = DECLARATIONS[word]
        if prev in MODIFIERS and word not in {'self', 'this', 'case'}:
            return -1.25 if prev == 'async' and word == 'def' else value - 0.45
        if previous.isspace() or '\n' in previous:
            if s.startswith(' '):
                return value
            factor = 0.90 if s.startswith('\t') else 0.65
            return value * factor
        if s.startswith('\t'):
            return value * 0.35
        if word == 'def':
            return -0.25
        if word == 'private' and s.startswith(' '):
            return 0.38
        if not s.startswith(' '):
            return -0.15 if word in {'public', 'void', 'self'} else -0.05
        return 0.12 if word in {'let', 'final', 'abstract', 'virtual'} else 0.0
    return 0.18 if word in {'return', 'try', 'break', 'switch', 'while'} else 0.0


def step(carry, prefix, upstream):
    previous = ''
    if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2]
    return None, float(response(prefix.token_strings[-1], previous))

programs.haiku:
"""Layer-0 MLP feature 3551 (down_proj): a conditional-"if" detector, negative on type and
declaration keywords.

Reads the current token (and whether it starts an indented line):
  * "if", "elif" (and capitalised "If"/"IF") push it strongly positive, about +1.7.
  * "unless" and German "wenn" are weakly positive, about +0.5.
  * control-flow words "return", "try", "else", "switch", "break", "throw" are slightly
    positive, about +0.2.
  * type and declaration keywords ("def", "fn", "func", "static", "void", "public",
    "private", "protected", "int", "char", "bool", "const", "var", "class", "struct")
    are negative. They are strongly negative (about -1.0) when they open an indented
    line, i.e. start a declaration, and only mildly negative (about -0.25) mid-sentence.
  * "self" is mildly negative (about -0.2).
Everything else is 0.
"""

READS = ()

IF_WORDS = {"if": 1.7, "elif": 1.7, "unless": 0.5, "wenn": 0.5}
CONTROL_WORDS = {"return", "try", "else", "switch", "break", "throw"}
DECL_WORDS = {
    "def", "fn", "func", "static", "void", "public", "private", "protected", "pub",
    "int", "char", "bool", "boolean", "double", "float", "const", "var", "class", "struct",
}


def opens_line(prev):
    """True if the previous token ends a line or is indentation."""
    return "\n" in prev or "\t" in prev or (prev.strip() == "" and len(prev) >= 2)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if word in IF_WORDS:
        return carry, IF_WORDS[word]
    if word in DECL_WORDS:
        return carry, -1.0 if opens_line(prev) else -0.25
    if word in CONTROL_WORDS:
        return carry, 0.2
    if word == "self":
        return carry, -0.2
    return carry, 0.0

programs.luna:
"""Recognize frequent grammatical tokens 'for' and 'from'."""

READS = ()

WORD_VALUES = {"for": 0.824, "from": 0.873}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    return None, float(WORD_VALUES.get(word, 0.0))

programs.sol:
"""Lexical streams: I/O streams and iterators, plus river/flow vocabulary.

This approximates the large positive responses, rather than small unrelated
token biases. Inflections and longer I/O names have weaker responses. Context only joins
split spellings and recognizes 'of' after stream or direction words; these
rules never cross a document boundary. All unrecognized tokens get zero.
"""

READS = ()
STREAM_FORMS = {
    'stream': 5.7, 'streams': 4.8, 'streaming': 2.5, 'streamed': 3.2,
    'streamline': 1.2, 'streamlined': 1.2, 'mainstream': 1.0,
    'upstream': 3.2, 'downstream': 2.6,
}
# East Asian stream, river, flow, swimming and wandering vocabulary.
RIVER_WORDS = {
    '溪': 5.2, '流': 1.8, '河': 1.0, '江': 1.0, '川': 1.3,
    '游': 1.3, '遊': 0.85,
    '上游': 3.3, '下游': 3.3, '上下游': 3.3,
    '河流': 1.4, '流水': 1.4, '水流': 1.4,
}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    token = raw.strip()
    word = token.lstrip('._-/(<').lower()
    previous = ''
    if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2].lower()
    prev_word = previous.strip().lstrip('._-/(<')
    value = 0.0

    if raw == ' of' and prev_word in {'stream', 'streams'}:
        value = 3.4 if prev_word == 'stream' else 2.7
    elif raw == ' of' and prev_word in {'upstream', 'downstream'}:
        value = 1.4
    elif prev_word == 'stream' and raw in {'ing', 'er', 's'}:
        value = 3.5 if raw == 's' else 2.0
    elif word == 'ream' and previous.endswith('st'):
        value = 3.3
    elif word in STREAM_FORMS:
        value = STREAM_FORMS[word]
        if raw == ' Stream':
            value = 4.9
        elif raw == 'stream' and previous.endswith('main'):
            value = 2.8
    elif word in {'inputstream', 'outputstream', 'datastream', 'istream', 'ostream'}:
        value = 3.8
    elif word == 'iostream':
        value = 1.9
    elif word.endswith('stream') and word != 'bloodstream':
        value = 2.3
    elif word in {'iterator', 'iterators'}:
        value = 2.6 if token[:1].isupper() or token.startswith('.') else 1.8
    elif word == 'iterable':
        value = 1.3 if token[:1].isupper() else 0.85
    elif word == 'iter':
        value = 1.8 if token.startswith('_') else 1.2
        if raw == 'iter':
            value = 0.25 if previous[-1:].isalpha() else 0.75
    elif word == 'itertools':
        value = 1.4
    elif word in {'river', 'rivers', 'creek', 'creeks', 'brook'}:
        value = 1.0
    elif token in RIVER_WORDS:
        value = RIVER_WORDS[token]
    return None, value

programs.luna:
"""A lexical sketch of the component's clearest cues.

It marks stream and waterway words, plus a few terms for data in feeds and
iterators; Chinese medicine tokens get a small negative value. Other tokens
get zero because this component is usually quiet.
"""
READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].casefold()

    if "downstream" in word or "upstream" in word:
        value = 2.8
    elif "outputstream" in word or "inputstream" in word:
        value = 2.2
    elif "stream" in word:
        value = 4.0
    elif "river" in word or "creek" in word:
        value = 1.0
    elif any(term in word for term in ("itertools", "ienumerable")):
        value = 1.1 if "ienumerable" in word else 1.5
    elif "iterator" in word or "iterable" in word:
        value = 1.0
    elif "feed" in word:
        value = 0.9
    elif "河" in word:
        value = 1.0
    elif "药" in word or "藥" in word:
        value = -0.8
    else:
