    'for', 'back', 'up', 'down', 'in', 'out', 'on', 'to',
    'north', 'south', 'east', 'west', 'left', 'right', 'rear', 'front',
}
ORIENTATION_WORDS = {'horizontal', 'vertical', 'reverse', 'fore', 'hind'}
ORIENTATION_TERMS = {
    'horizontally', 'vertically', 'worldwide', 'downstream', 'sidew',
    'upright', 'uphill', 'downhill', 'upside', 'zenith', 'hacia',
}


