    stem = previous.strip().lstrip('._-/').lower()

    if word in {'forward', 'backward', 'upward', 'downward'}:
        if word == 'forward' and stem in {'put', 'straight'}:
            return -5.0
        if word == 'forward' and stem in {'move', 'moving', 'go', 'going', 'come'}:
            return -7.8
        return -7.0 if token.startswith(' ') else -6.0
