        return -5.0 if word == 'ward' else -4.0
    if word in {'toward', 'towards', 'afterward', 'afterwards'}:
        return -2.1
    if word == 'forth':
        return -3.8 if stem == 'and' else -2.1
    if word in {'clockwise', 'counterclockwise', 'sideways'}:
        return -4.1
    if token == 'wise':
        return -3.8 if stem.endswith(('clock', 'lock', 'step')) else -2.1
    if word == 'pairwise' or token == '-wise':
