        return -0.8
    if word == 'up':
        return -0.12
    if word in {'direction', 'directions'}:
        return -0.7
    if word in ORIENTATION_WORDS:
        return -0.6
    if word in ORIENTATION_TERMS or word == 'straightforward':
        return -1.2
