Single letters, capitals and punctuation
also support it; longer lowercase words (especially whole words or control-flow
keywords) suppress it. A space before the parenthesis strengthens the signal.
Nearby repeated openings are weaker than the first opening in a document.
The document separator and literal 'assistant' token get fixed positive values.
Other tokens get zero; state resets at each document boundary.
"""
import math

READS = ()
CONTROL_WORDS = {'if', 'for', 'while', 'switch'}


def preceding_score(token):
    word = token.strip()
    length = min(len(word), 14)
    score = 0.59
    if word and word[-1].isdigit():
        score += 2.08
    elif length == 1 and word.isalpha():
        score += 0.80
    elif word.isalpha() and word.islower():
        score += 0.51 - 0.092 * length
        if token[0].isspace():
            score -= 0.33
    elif word.isalpha() and word.istitle():
        score += 0.49 - 0.075 * length
        if token[0].isspace():
            score += 0.18
    elif word.isalpha() and word.isupper():
        score += 1.15 - 0.230 * length
    elif word and not any(c.isalnum() for c in word):
        score += 0.93 + 0.082 * length
    elif not word:
        score += 1.15
        if not token:
            score += 0.54
    if word in CONTROL_WORDS:
        score -= 0.55
    return score


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, distance, seen, digits = '', 999, False, 0
    else:
        _, previous, distance, seen, digits = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if token == '<|endoftext|>':
        value = 1.33
    elif token == 'assistant':
        value = 0.92
    elif '(' in token or '（' in token:
        score = preceding_score(previous)
        if digits:
            score += 0.32 * (min(digits, 3) - 1)
        score += 0.20 if not seen else 0.0
        score -= 0.33 * math.exp(-distance / 12.0)
        if token == ' (':
            value = score
        elif token == '(' or token == '（':
            value = -1.00 + 1.22 * score
        elif '()' in token:
            value = -0.13 + 0.31 * score
        elif token[0].isspace():
            value = -0.03 + 0.64 * score
        elif not token.startswith('('):
            value = -0.05 + 0.21 * score
        elif token[1:].isalpha():
            if len(token) == 2:
                value = -0.47 + 0.82 * score
            else:
                value = -0.09 + 0.38 * score
        elif token.startswith('(\"') or token.startswith("('"):
            value = -0.35 + 0.76 * score
        else:
            value = -0.35 + 0.84 * score
    if '(' in token or '（' in token:
        distance, seen = 0, True
    else:
        distance += 1
    digits = digits + len(token) if token.isascii() and token.isdigit() else 0
    return (doc, token, distance, seen, digits), float(value)

