"""Opening-parenthesis detector for layers.0.mlp.down_proj:3561.

The component fires on the token that opens a parenthetical, and on the
end-of-document token. Its size depends on what comes just before the paren:

- after a number ("2010 (", "12 km ("): strongest, about 2.9 for " (";
- after punctuation or a space ('said: (', '"('): moderate, about 1.4;
- after a word: moderate for a spaced " (" (about 0.2 after a common
  lowercase word, about 0.9 after a capitalized or word-fragment token);
- glued to a word, as in a function call "print(": about 0.

Also: <|endoftext|> about 1.3, the chat-role word "assistant" about 0.9,
and "/" right after a digit about 0.4. Everything else is 0.
"""

READS = ()
EOT = "<|endoftext|>"
OPEN_PARENS = ("(", "（")


def step(carry, prefix, upstream):
    if prefix.position == 0:
        return None, 0.0
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2]
    last = prev[-1:]
    spaced = cur.startswith(" ")
    opens = cur.lstrip(" ")[:1] in OPEN_PARENS
    if cur == EOT:
        v = 1.33
    elif cur == "assistant":
        v = 0.9
    elif opens:
        if last.isdigit():
            v = 2.9 if spaced else 1.6
        elif last.isalpha():
            if not spaced:
                v = 0.1
            elif prev.startswith(" ") and prev[1:2].islower():
                v = 0.2
            else:
                v = 0.9
        else:
            v = 1.4 if spaced else 1.0
    elif cur == "/" and last.isdigit():
        v = 0.4
    else:
        v = 0.0
    return None, float(v)


if __name__ == "__main__":
    # Quick self-check on a made-up token list.
    toks = ["In", " 2010", "1", " (", "born", ")"]
    class P:
        pass
    carry = None
    for i in range(len(toks)):
        p = P()
        p.token_strings = tuple(toks[: i + 1])
        p.position = i
        carry, v = step(carry, p, {})
        print(repr(toks[i]), v)

