"""Word-level 'continue' detector: one MLP unit (3562) of layer 0's down_proj.

It reads the current token and the one before it, not the wider context, and fires by tier:
  - the verb "continue" in any form (continue, continued, continues, continuing): ~8
  - a word split as "contin" + "ued"/"uing"/"uation"/"ual": ~8 on the second piece
  - "continuation" and "contin" fragments: ~5
  - translations of "continue" (продолж-, 続, 續, 续, 繼, 持续, 连续, 后续): ~4
  - continuous, continuously, continually, ongoing, proceed, weiter, seguir: ~2
  - words of going on, starting, or what comes next (next, further, still, keep, remain,
    stop, begin, start, break, include, future, another): ~1
  - "to"/"of" directly after a continue-form ("continue to", "continuation of"): ~3
Everything else is 0.
"""

READS = ()

FORMS = {"continue", "continued", "continues", "continuing"}
FRAGMENTS = {"contin", "continu", "continua", "continuation"}
SPLIT_ENDINGS = {"uing", "ued", "uation", "ual", "uous"}
TRANSLATION = ("продолж", "続", "續", "续", "繼", "持续", "连续", "后续")
TIER2 = {"continuous", "continuously", "continually", "ongoing", "proceed", "proceeds",
         "proceeding", "ceased", "weiter", "weitere", "seguir"}
TIER1 = {"next", "further", "still", "keep", "kept", "remain", "remained", "stop", "stopping",
         "began", "begin", "begins", "start", "started", "starting", "starts", "break",
         "include", "including", "future", "extend", "extends", "resume", "another", "repeat"}

def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    y = s.strip().lower()
    same_doc = len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if y in FORMS:
        value = 8.0
    elif y in SPLIT_ENDINGS and prev.startswith("contin"):
        value = 8.0
    elif y in FRAGMENTS:
        value = 5.0
    elif any(k in s for k in TRANSLATION):
        value = 4.0
    elif y in TIER2:
        value = 2.0
    elif y in TIER1:
        value = 1.0
    elif (prev in FORMS or prev == "continuation") and y in ("to", "of"):
        value = 3.0
    else:
        value = 0.0
    return None, value

