    elif word.startswith(("continue", "continuing")):
        value = 8.4
    elif word.startswith("continua"):
        value = 4.8
    elif word.startswith("contin"):
        value = 5.5
    elif word in NEXT_WORDS:
        if word in {"ongoing", "continuous", "continuously"}:
            value = 2.4
        elif word.startswith("proceed"):
            value = 1.8
        else:
            value = 1.2
    elif word in PROCESS_WORDS:
        value = 0.7
    elif word == "to" and previous.startswith(("continue", "continuing")):
        value = 3.2
    elif word.startswith("uation") and previous.startswith("contin"):
