programs.sol:
"""Detect common forms of English 'be' and their immediate grammatical context.

Plural-looking preceding words favor 'are/were', singular-looking words
favor 'is/was'. Pronouns, relative/question words, and locative 'there/here'
have their own responses. This is a spelling-based approximation, not a parser.
'Be/been' respond to auxiliaries; existential 'there' suppresses them even
across auxiliaries and adverbs. End-of-text gives a fixed negative response.
The initial pieces of negated be-forms get a weaker, shifted response.
Related contractions and interrogative 'do' have fixed responses.
Other tokens are zero. State resets at document boundaries.
"""
import re

READS = ()
# Columns: is, was, are, were.
# Approximate response strengths fitted from training.
SUBJECTS = {
    'ordinary word': (0.86, 1.00, 0.01, 0.36),
    'unspaced word': (0.69, 0.86, -0.10, 0.41),
    'plural': (0.28, 0.49, 1.02, 1.19),
    'symbol': (0.49, 0.71, 0.10, 0.53),
    'it': (0.72, 0.85, -0.76, -0.85),
    'he/she': (0.83, 1.05, -0.30, -0.19),
    'i': (0.44, 0.75, 0.15, 0.30),
    'we/you': (0.40, 0.61, 0.72, 1.03),
    'they': (0.40, 0.61, 0.92, 1.13),
    'this': (0.83, 1.06, -0.08, 0.23),
    'these/those': (0.39, 0.61, 0.78, 1.12),
    'relative': (0.62, 0.85, -0.12, 0.25),
    'here': (0.67, 0.87, -0.93, -0.50),
    'there': (-0.06, 0.12, -1.05, -0.63),
    'what': (0.94, 1.03, -2.18, -1.50),
    'question': (0.27, 0.43, -0.86, -0.50),
    'conjunction': (0.28, 0.61, 0.47, 0.75),
    'function': (0.54, 0.74, 0.25, 0.50),
}
MODALS = {'will', 'would', 'can', 'could', 'may', 'might',
          'must', 'should', 'shall', 'cannot'}
ADVERBS = {'not', 'also', 'only', 'always', 'never', 'then', 'still',
           'even', 'now', 'already', 'ever', 'just', 'yet', 'sometimes', 'often'}
PLURALS = {'people', 'children', 'men', 'women', 'teeth', 'feet', 'mice',
           'bacteria', 'spectra', 'larvae', 'both', 'all'}
SINGULAR_S = {'news', 'diabetes', 'physics', 'mathematics', 'economics', 'species'}
FUNCTIONS = {'a', 'an', 'the', 'of', 'in', 'on', 'for', 'by', 'with', 'from',
             'as', 'at', 'its', 'his', 'her', 'their', 'our', 'your', 'to'}


def word(raw):
    match = re.search(r'[A-Za-z]+$', raw.strip())
    return match.group().lower() if match else ''


def subject(raw):
    w = word(raw)
    if w in ('it', 'i', 'they', 'this', 'here', 'there', 'what'):
        return w
    if w in ('he', 'she', 'we', 'you', 'these', 'those'):
        return {'he': 'he/she', 'she': 'he/she', 'we': 'we/you',
                'you': 'we/you', 'these': 'these/those', 'those': 'these/those'}[w]
    if w in ('who', 'which', 'that'):
        return 'relative'
    if w in ('how', 'why', 'where', 'when'):
        return 'question'
    if w in ('and', 'or', 'but', 'if', 'than', 'else'):
        return 'conjunction'
    if w in FUNCTIONS:
        return 'function'
    plural = (w.endswith('s') and not w.endswith(('ss', 'us', 'is'))
              and w not in SINGULAR_S) or w in PLURALS
    if plural:
        return 'plural'
    if len(w) <= 1:
        return 'symbol'
    return 'ordinary word' if raw.startswith(' ') else 'unspaced word'


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous, existential = '', False
    if carry is not None and carry[0] == doc:
        _, previous, existential = carry
    w = word(previous)
    value = 0.0
    finite = (' is', ' was', ' are', ' were')
    negative = (' isn', ' wasn', ' aren', ' weren')
    if token == '<|endoftext|>':
        value = -1.24
    elif token in finite or token in negative:
        column = (finite if token in finite else negative).index(token)
        value = SUBJECTS[subject(previous)][column]
        if token in negative:
            scale, offset = ((0.63, -0.29), (0.68, -0.26),
                             (0.80, -0.35), (0.86, -0.54))[column]
            value = scale * value + offset
    elif token == ' be':
        if w in MODALS:
            value = 1.02 if w in ('will', 'would') else 1.19
        elif w == 'to':
            value = 0.97
        elif w in ADVERBS or w.endswith('ly'):
            value = 0.91
        elif previous in ("'t", '’t', "'ll", '’ll', "'d", '’d'):
            value = 0.94
        else:
            value = 0.25
        value -= 0.72 if existential else 0.0
    elif token == ' been':
        value = 0.96 if w in ('has', 'have', 'had') else 0.77
        if previous in ("'s", '’s'):
            value = 0.51
        value -= 0.75 if existential else 0.0
    elif token == ' am' and w == 'i':
        value = 0.21
    elif token in ("'re", '’re'):
        value = 0.35 if w == 'they' else 0.21
    elif token in ("'s", '’s') and w == 'there':
        value = -0.71
    elif token == ' do' and w in ('what', 'how', 'why', 'where', 'when'):
        value = -1.36 if w == 'what' else -0.42

    current = word(token)
    bridge = (current in MODALS or current in ADVERBS or current.endswith('ly')
              or current in ('has', 'have', 'had', 'to', 'hasn', 'haven')
              or token in ("'s", '’s', "'ve", '’ve', "'t", '’t', "'ll", '’ll'))
    existential = current == 'there' or (existential and bridge)
    return (doc, token, existential), float(value)

