    token = prefix.token_strings[-1]
    text = token.strip()
    if text in CONVERSATION_MARKERS:
        return None, CONVERSATION_MARKERS[text]
    if not text:
        return None, 0.0003
    names = [unicodedata.name(c, '') for c in text]

    def majority(script):
        return sum(n.startswith(script) for n in names) > len(names) / 2

    space = token.startswith(' ')
    if majority('CYRILLIC'):
        value = 0.016 if len(text) == 1 else (0.050 if space else 0.028)
    elif majority('HANGUL'):
        value = 0.080 if space else 0.044
    elif majority('CJK'):
        value = 0.015 if len(text) == 1 else (0.003 if len(text) == 2 else -0.018)
    else:
        for script, value in SCRIPT_MEANS.items():
            if majority(script):
