    'none': .35, 'nobody': .54, 'neither': .23, 'nor': .18,
    'non': .27, 'dont': .45, 'cant': .48, 'didnt': 1.,
    'doesnt': .71, 'wont': .45, 'unable': .30, 'hardly': .57,
    'nicht': .82, 'kein': .56, 'keine': .29, 'keinen': .41,
    'nie': .15, 'nichts': .39, 'niet': .44, 'geen': .30,
    'pas': .58, 'jamais': .48, 'não': .50, 'nunca': .53,
    'не': .49, 'нет': .34, 'нельзя': .33, 'никогда': .29,
    'không': .41, 'tidak': .33, 'لا': .50, 'ليس': .72,
    'ない': .31, 'なく': .22, '못': .62, '않': .56,
