    raw = prefix.token_strings[-1]
    word = raw.strip().casefold()
    prev = recent[-1] if recent else ''
    context = -.58 * any(w in {'if', 'whether', 'unless'} for w in recent)
    context += .44 * ('i' in recent[-8:])
    context += .23 * ('you' in recent[-8:]) + .23 * ('we' in recent[-8:])
    value = 0.
    if word in {'not', 'no'}:
        is_not = word == 'not'
        value = (NOT_AFTER.get(prev, 1.40) if is_not
                 else NO_AFTER.get(prev, .60))
        if prev in BE_CONTRACTIONS:
            value = 1.80 if is_not else 1.20
        value += context * (1. if is_not else .4)
        if raw.strip().isupper():
            value -= .30 if is_not else .22
        elif raw.strip().istitle():
            value += .25 if is_not else .12
        if not raw.startswith(' '):
            value -= .17 if is_not else .20
    elif word in {"'t", '’t', "n't", 'n’t'} and prev in NEGATIVE_STEMS:
        value = 1.39 + .7 * context + .31 * ('’' in word)
        if prev in {'can', 'couldn'}:
            value += .31
        elif prev == 'doesn':
            value -= .30
        elif prev in {'isn', 'aren', 'haven', 'hadn', 'wouldn', 'shouldn'}:
            value -= .10
    elif word in NEGATIVE_WORDS:
        value = NEGATIVE_WORDS[word]
        if word == 'never':
            value += .25 * context
        elif word == 'cannot' and raw.strip().istitle():
            value -= .30
        elif word == 'none' and raw.strip() == 'None':
            value = 0.  # The Python null literal, not the English negative.
        elif word == 'pas' and raw.strip().isupper():
            value = .16  # Suppress uppercase PAS.
    elif word.endswith('不是'):
        value = .85
    elif word.endswith('不') and len(word) <= 3:
        value = .50
    elif word in {'不能', '不会', '不會', '不要', '不可', '不可能', '不敢'}:
        value = .35
    elif word in {'没', '沒', '没有', '沒有', '非'}:
        value = .38
    elif word in {'无法', '無法', '并非', '並非'}:
        value = .60
    return (doc, (recent + (word,))[-12:]), float(value)

