"""Mostly an m/M spelling detector, with a little word-continuation memory.

Initial m's are strongest, capitals and short fragments stronger still;
common grammatical words and verbs are weaker. Analogous m letters/sounds
in other scripts and some Chinese m-word translations also contribute.
A final m can spill onto the next unspaced token, but a repeated m there
is suppressed. Small secondary responses cover chat delimiters, arrows,
and indentation near 16 or 32 spaces. Coefficients fit training rows.
"""
import re

READS = ()
FUNCTION_WORDS = set(
    'me my mine myself may might must many more most much maybe'.split()
)
COMMON_VERBS = set(
    'make makes making made mean means meaning meant meet meets meeting '
    'met move moves moving moved manage manages managing managed'.split()
)
M_KANA = set('まみむめもマミムメモ')
# Mandarin characters whose readings begin with m.
M_HANZI = set(
    '妈嗎吗麻马馬玛瑪码碼骂罵嘛埋买買卖賣迈邁麦麥脉脈满滿慢漫曼蛮蠻'
    '忙芒盲茫莽猫貓毛矛茅茂冒帽贸貿貌么麼没沒枚玫梅媒煤每美妹媚'
    '门門闷悶们們萌盟蒙猛梦夢孟眯迷谜謎米秘密蜜眠绵綿棉免勉娩冕面'
    '苗描瞄妙灭滅民珉敏闽閩名明鸣鳴铭銘命缪繆摸模膜摩磨魔蘑末沫陌'
    '莫墨默漠谋謀牟某母亩畝姆牡拇木目牧墓募幕慕穆暮沐'
)
# me/my, month, many/more, method, manage, market, medical, media,
# material, machine, modify, movie, marketing, memory, member, menu.
M_TRANSLATIONS = set(
    '我 我的 月 一个月 多 更多 方法 方式 管理 市场 市值 医疗 医保 '
    '媒体 材料 机器 机 機 修改 电影 营销 内存 成员 菜单'.split()
)
CHAT_MARKERS = {
    '<|im_start|>': 1.77, '</think>': 1.60,
    '</tool_response>': 1.18, '<think>': 0.49,
}


def spelling_value(token):
    s = token.lstrip()
    first_letter = re.search('[A-Za-z]', s)
    initial_m = bool(first_letter and first_letter[0].lower() == 'm')
    value = 0.005
    if initial_m:
        word = s[first_letter.start():]
        lower = word.lower()
        value += 1.89
        if word[0] == 'M':
            value += 0.58
        if len(word) == 1:
            value -= 0.22
        elif len(word) <= 3:
            value += 0.28
        elif len(word) >= 8:
            value -= 0.09
        if lower in FUNCTION_WORDS:
            value -= 0.51
        if lower in COMMON_VERBS:
            value -= 0.27
        if len(word) >= 5 and lower.endswith(('s', 'ing', 'ed')):
            value -= 0.17
        if word.startswith('Mc'):  # Scottish/Irish surname prefix
            value += 1.34
    elif 'm' in s.lower():
        if s.lower().index('m') == 1:
            value += 0.24
        if s.lower().endswith('m'):
            value -= 0.075
        if re.search('[a-z_.]M', s):  # m at a camelCase/identifier boundary
            value += 1.08

    first = s[:1]
    if first in ('м', 'М'):
        value += 1.31 + (0.52 if len(s) <= 3 else 0.0)
    if first == 'م':
        value += 1.82 + (0.17 if len(s) == 1 else 0.0)
    elif s.startswith(('الم', 'والم', 'للم', 'بالم')):
        value += 2.65  # Arabic article/preposition followed by meem
    if first in ('μ', 'µ', 'Μ'):
        value += 1.06
    if first in M_KANA:
        value += 1.36 + (0.25 if s == 'も' else 0.0)
    elif any(ch in M_KANA for ch in s):
        value += 0.32
    if first and 0xAC00 <= ord(first) <= 0xD7A3:
        if (ord(first) - 0xAC00) // 588 == 6:  # Hangul initial mieum
            value += 1.29
    if first in M_HANZI:
        value += 1.11
    if s in M_TRANSLATIONS:
        value += 1.19

    if token in CHAT_MARKERS:
        return CHAT_MARKERS[token]
    if s in ('=>', '⇒'):
        value += 0.59
    if token.isspace():
        spaces = token.count(' ')
        if 14 <= spaces <= 16 or 29 <= spaces <= 32:
            value += 0.72
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    value = spelling_value(token)
    if token[:1].isalnum():
        initial_m = token.lstrip()[:1].lower() in ('m', 'м')
        previous_m = previous[-1:].lower() in ('m', 'м', 'μ', 'م')
        if previous_m:
            value += -2.03 if initial_m else 0.70
        elif initial_m and previous[-1:].isalpha():
            value -= 0.56
    return (doc, token), float(value)

"""Detect backslash-escaped quotation marks in the current token.

Escaped double quotes are strongest at the token's end, especially after
whitespace. Surrounding quotes, closing punctuation, or another escape
weaken the response. Escaped apostrophes, the HTML quote entity, and two
standalone diacritic marks have weaker positive responses. Ordinary tokens
are zero: this deliberately omits small, word-specific fluctuations.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if '\\"' in token:
        before, after = token.split('\\"', 1)
        if before.endswith('\\'):
            value = 0.4
        elif '\\"' in after:
            value = 1.4
        elif not after:
            if '"' in before or "'" in before:
                value = 1.2
            elif before.isspace():
                value = 2.5
            elif before.endswith(('.', '}')):
                value = 1.6
            else:
                value = 2.1
        elif after.startswith('\\'):
            value = 1.23
        elif after.startswith((')', ']', '>')):
            value = 0.9
        elif '\\' in after or '"' in after:
            value = 0.8
        else:
            value = 1.1
    elif "\\'" in token:
        before, after = token.split("\\'", 1)
        value = 0.45 if "'" in before + after else 1.1
    elif token == '&quot':
        value = 0.7
    elif token == '᾽':  # Greek koronis
        value = 0.6
    elif token == '¨':  # Spacing diaeresis
        value = 0.95
    else:
        value = 0.0
    return None, value

"""A sparse procedural-transition detector.

Negative pulses mark 'now', purpose/infinitive 'to', requirements,
first/next steps and proof vocabulary. Paragraph starts, first-person
planning, and recent numbers or mathematical notation strengthen them.
A positive exception recognizes 'let me/us see'. Memory resets between
documents.
The many small responses to other words are deliberately left at zero.
"""
READS = ()

BASE = {
    'now': -0.35, 'need': -0.22, 'must': -0.17,
    'first': -0.13, 'next': -0.20, 'we': 0.04,
    'proof': -0.30, 'prove': -0.28, 'compute': -0.27,
    'proceed': -0.55, 'goal': -0.15, 'aim': -0.20,
    'start': -0.15, 'starting': -0.17, 'remaining': -0.10,
    'needs': -0.12, 'requires': -0.12, 'hmm': -0.19,
    'analyze': -0.16, 'expanding': -0.25, 'proceeding': -0.28,
    'moving': -0.15, 'reduced': -0.16, 'becomes': -0.16,
    'formal': -0.20, 'interested': -0.16,
}
MATH_GAIN = {
    'now': 0.7, 'to': 0.16, 'need': 0.9, 'must': 0.7,
    'first': 0.25, 'next': 0.65, 'we': 0.3, 'proof': 0.5,
}
MATH_SYMBOLS = set('=^±×÷√∑∏∫≤≥≠∞⇒∂²³')
FIRST_PERSON = {'we', 'i', 'me', 'us'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
    previous, before, maths = ('', '', 0.0) if initial else carry[1:]
    token = prefix.token_strings[-1]
    text = token.strip()
    word = text.lower()
    prev, older = previous.strip().lower(), before.strip().lower()
    cap = text[:1].isupper()
    bare = not token[:1].isspace()
    paragraph = '\n\n' in previous
    newline = '\n' in previous
    value = BASE.get(word, 0.0)

    if cap:
        value = {'now': -0.65, 'to': -0.70, 'we': -0.08,
                 'next': -0.50, 'proof': -0.55}.get(word, value)
    if cap and bare and newline:
        value -= {'now': 0.25, 'first': 0.30, 'next': 0.33,
                  'we': 0.10, 'proof': 0.15}.get(word, 0.0)
        if paragraph:
            value -= {'now': 0.55, 'first': 0.35,
                      'next': 0.40, 'we': 0.20}.get(word, 0.0)
    if prev in FIRST_PERSON:
        value -= {'now': 0.65, 'first': 0.40, 'next': 0.40,
                  'will': 0.16, 'can': 0.16, 'want': 0.16}.get(word, 0.0)
        if word == 'need':
            value -= 0.60 if prev == 'we' else 0.40
            if previous.strip() == 'We':
                value -= 0.35
    if word == 'now' and prev in {'so', 'notice', 'consider', 'observe'}:
        value -= 0.50
    if word == 'now' and older in FIRST_PERSON and prev in {
        'can', 'will', 'may', 'also', 'just', 'still', 'are',
    }:
        value -= 0.60
    if word == 'must' and prev in {'we', 'this'}:
        value -= 0.22
    if word == 'need' and prev == 'the':
        value += 0.12
    if word == 'first' and prev in {'to', 'of', 'by', 'in', 'from'}:
        value -= 0.15
    if word == 'proof' and prev == 'the':
        value -= 0.18
    if word == 'to':
        if cap and bare:
            value = -0.40 if not newline else -0.85 - 0.20 * paragraph
        elif not cap:
            if prev in {'need', 'needs', 'order'}:
                value = -0.15 - 0.35 * (older in FIRST_PERSON)
                value -= 0.25 * (before.strip() == 'We')
            elif prev in {'equivalent', 'reduces', 'simplifies', 'ifies', 'proceed'}:
                value = -0.60
            elif prev in {'want', 'able', 'trying', 'difficult', 'ability', 'have'}:
                value = 0.10
            elif ',' in previous:
                value = -0.14
    if word == 'see' and prev in {'me', 'us', "'s", '’s'}:
        value = 0.42
    if initial:
        value = {'now': -1.73, 'we': -0.63 if cap else -0.34}.get(word, value)
        if word == 'to':
            value = (-1.66 if bare else -1.96) if cap else -0.17
    else:
        value -= MATH_GAIN.get(word, 0.0) * maths
    cue = (any(c in MATH_SYMBOLS for c in text)
           or text.startswith('\\') or text.isdecimal())
    maths = 0.85 * maths + 0.15 * float(cue)
    return (doc, token, previous, maths), float(value)

