"""Predict the component's negative pulse on planning and problem-solving cues.

It responds most to words that announce a next step, an obligation, or a
calculation. This compact lexical rule misses context-specific pulses and the
component's small background variation.
"""

READS = ()

SEQUENCE = {"now", "next", "first", "second", "start", "starting"}
NECESSITY = {"need", "needs", "must", "require", "requires"}
PROBLEM_WORK = {
    "goal", "focus", "compute", "solve", "calculate", "derive",
    "prove", "find", "expand", "simplify",
}
TO_CUES = NECESSITY | PROBLEM_WORK | SEQUENCE | {"want", "try", "begin"}
SCALE = 0.76


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip(
        " \t\r\n.,:;!?()[]{}\"'*-_"
    )
    lower = word.lower()

    if lower in NECESSITY:
        value = -0.40
    elif lower in SEQUENCE:
        value = -0.34
    elif lower in PROBLEM_WORK:
        value = -0.30
    elif lower == "to":
        value = -0.55 if word[:1].isupper() else 0.0
        same_document = (
            len(prefix.token_strings) > 1
            and prefix.document_ids[-1] == prefix.document_ids[-2]
        )
        if value == 0.0 and same_document:
            previous = prefix.token_strings[-2].strip(
                " \t\r\n.,:;!?()[]{}\"'*-_"
            ).lower()
            if previous in TO_CUES:
                value = -0.30
    else:
        value = 0.0
    return None, float(value * SCALE)

