    if low in {'everyone', 'everybody'}:
        return -0.494
    if low in {'individual', 'individuals', 'personally', 'mankind'}:
        return -0.196
    if low == 'readme':
        return 0.30 if token.startswith(' ') else 0.52
    if low == 'serde':
        return 0.51
    if text == '/issues':
        return -0.53
    if text == '/workspace':
        return -0.12
    if text in {'という', 'いう', 'と言う', 'っていう'}:
        return 0.606
    if text in {'これ', 'それ', 'ここ', 'そこ', 'あれ'}:
        return -0.473
    if text in {'どんな', 'どの', 'どういう', 'なんて', 'あの'}:
        return 0.46  # Adnominal question/demonstrative forms.
    if text in {'したもの', 'るもの', 'なもの'}:
        return -0.99  # A verb/adjective turned into a reference to a thing.
    if text.startswith('なの') or text in {'るので', 'ないので', 'ですし', 'などで', 'などが'}:
