                return -0.603
            if action == 'to' and obj == 'string':
                return 0.122
            return {
                'get': -0.249, 'set': -0.324, 'add': -0.223,
                'new': -0.576, 'with': -1.125,
                'by': -0.624, 'from': -0.549, 'of': -0.584,
