        return -1.01
    if text in PEOPLE:
        return -0.53
    if text in FAMILY:
        return -0.25
    if text in JOB_TITLES:
        return -0.09
    if text in {'本书', '本書'}:
        return -2.145
    if text in {'本文', '本站', '本网'}:
        return -0.787
    if text in {'个小', '一个小', '一个好的', '一个新的', '一个重要'}:
        return -1.431
