"""Rough explanation of layers.0.mlp.down_proj:3570 (a diffuse, mostly negative feature).

What it does: this component goes negative on a few kinds of tokens, and is near zero
elsewhere:
  1. words for people in a general sense (个人, 他人, 本人, 有人, 大家, 男人, 的人,
     everyone, everybody, anyone, individuals), the strongest group;
  2. Japanese nominalisers 'こと' / 'ること' (as in する→すること, とる→ること);
  3. code accessor names such as .getName, .setText, getItem, setTitle;
  4. Chinese words of three or four characters (noun phrases such as 一定程度,
     专业知识, 这场比赛), more negative the longer the word.
Everything else predicts 0. The values are hand-set group averages from ~2000
training rows, not a fitted model, so the program explains only a small part of the
activation's variance.
"""
import re

READS = ()

PEOPLE_WORDS = {"个人", "他人", "本人", "有人", "大家", "男人", "女人", "每个人", "一个人",
                "有些人", "其他人", "很多人", "大多数人", "业内人士", "everyone", "everybody",
                "anyone", "anybody", "individuals", "individual", "someone"}
CODE_ACCESSOR = re.compile(r"^\.?(get|set)[A-Z]|^\.(get|set)")
CJK_WORD = re.compile(r"[一-鿿]+")


def _value(tok):
    s = tok.strip()
    if s in PEOPLE_WORDS or s.lower() in PEOPLE_WORDS:
        return -0.6
    if s.endswith("人") and CJK_WORD.fullmatch(s):
        return -0.2
    if s in ("こと", "ること", "ことが", "すること", "ということ", "ことは"):
        return -0.7
    if CODE_ACCESSOR.match(s):
        return -0.3
    if CJK_WORD.fullmatch(s):
        if len(s) == 4:
            return -0.35
        if len(s) == 3:
            return -0.1
    return 0.0


def step(carry, prefix, upstream):
    return None, _value(prefix.token_strings[-1])

