programs.haiku:
"""Layer-0 MLP unit that reads French pronouns and determiners in French text.

It fires on subject pronouns (il, ils, elle, on, je, tu, ce, cela, and the elided
forms qu'il, qu'on) and on possessive/demonstrative determiners (sa, son, ma, mon,
ces, cet). The activation is (a per-word weight) x (how French the recent text is).
French-ness is the share of French function words among the function words of the last
40 tokens of the same document. Italian "il", English "on" and the like stay near 0.
"""

FRENCH_WORDS = frozenset(
    "le la les de des du un une et est que qui à au aux en dans pour pas ne se sur par avec "
    "ce cette ces son sa ses il elle ils elles on nous vous je tu mais ou donc car été sont "
    "être avoir était très aussi".split()
)
ENGLISH_WORDS = frozenset(
    "the and of to is in that it for was with as on be are this by from at or an not".split()
)
SUBJECT = {"il": 2.5, "ils": 2.8, "elle": 2.0, "on": 1.5, "je": 1.8, "tu": 2.0,
           "cela": 2.9, "ce": 1.8}
DETERMINER = {"sa": 1.5, "son": 0.8, "ses": 1.1, "ma": 0.8, "mon": 0.8, "mes": 1.0,
              "ces": 1.5, "cet": 1.8}
WEAK = {"ne": 0.9, "à": 0.7, "se": 0.4, "nous": 0.7, "vous": 0.7}
WINDOW = 40
READS = ()


def pronoun_weight(token):
    word = token.strip().lower()
    if token.startswith(("'", "’")):  # elided forms: qu'il, qu'on, l'on
        word = token[1:].lower()
        return SUBJECT.get(word, 0.0)
    if token.startswith(" "):
        return SUBJECT.get(word, DETERMINER.get(word, WEAK.get(word, 0.0)))
    return 0.0


def french_share(words):
    french = sum(w in FRENCH_WORDS for w in words)
    english = sum(w in ENGLISH_WORDS for w in words)
    return french / (french + english) if french + english else 0.0


def step(carry, prefix, upstream):
    t = prefix.position
    docs = prefix.document_ids
    start = max(0, t - WINDOW)
    while start < t and docs[start] != docs[t]:
        start += 1
    words = [s.strip().lower() for s in prefix.token_strings[start:t]]
    weight = pronoun_weight(prefix.token_strings[t])
    return None, weight * french_share(words)

