STRONG_PERSON_ENDINGS = set('気气氣妻材力情形群教类類工影文寿壽')
MEDIUM_PERSON_ENDINGS = set('間间事物道才面海妖祸禍数數体體口身种種族缘緣際知')
PERSON_ENDINGS = set('马馬士血目名本母们們節节眼美秀意機机街称稱心格設设')
GRAMMATICAL_ENDINGS = set('的了是在有和与與をにはがもとへ')
