FUNCTION_WORDS = {'a', 'an', 'the', 'of', 'to', 'by', 'from', 'is', 'was', 'that'}
INDEFINITE_PEOPLE = {
    'someone', 'somebody', 'anyone', 'anybody', 'everyone', 'everybody',
}
PEOPLE = {'person', 'people', 'student', 'customer', 'consumer', 'family'}
CUES = {'human', 'user', 'man', 'personal'} | INDEFINITE_PEOPLE | PEOPLE


def person_completion(s):
    if not s or not s[0].isalpha():
        return 0.0
    if len(s) == 1 and s in STRONG_PERSON_ENDINGS:
        return 3.2
    if len(s) == 1 and s in MEDIUM_PERSON_ENDINGS:
        return 2.2
    if len(s) == 1 and s in PERSON_ENDINGS:
        return 1.8
    if s in {'気が', '間に', '世间', '所得税'}:
        return 1.9
    if s in {'情報', '感觉', '的には', '资料', '暮らし'}:
        return 1.0
