        if word in {'body', 'life', 'nature', 'interaction', 'language', 'experience'}:
            return 1.05
        return 0.25 if word in FUNCTION_WORDS else 0.5
    if previous == 'user':
        if word in {'-doc', '-agent', '-images', 'generated'}:
