        if word == 'else':
            return 0.85
        if word == 'who':
            return 0.28
        return 0.15 if word in FUNCTION_WORDS else 0.3
    if previous == 'personal':
        return 0.4 if word in {'information', 'experience', 'injury', 'data'} else 0.2
    if word in {'service', 'services', 'body', 'satisfaction'}:
