"""layers.0.mlp.down_proj:3573: the second half of a compound that starts with 人 or "human".

"人" (person) and "human" are often the first part of a word or fixed phrase: 人气 (popularity),
人妻, 人类, 人群, "human rights", "human resources", "/usr/local", "someone else". This
component fires on the token that completes such a compound, when the next token is a noun-like
word and not punctuation, a particle or a clause-starting function word. It is strongest after
人 and "human", weaker after "someone", "man", "personal" and "customer", and close to zero
everywhere else. Its predictions are small, but they follow the places where it matters most.
"""

import unicodedata

READS = ()

# Mean activation on the token after each word (rounded from a sample of training text).
PRIMING = {
    "human": 0.6, "usr": 0.7, "man": 0.3, "someone": 0.3, "somebody": 0.35, "anyone": 0.25,
    "everyone": 0.25, "personal": 0.25, "customer": 0.25, "user": 0.1,
}

# Words that start a new clause or phrase rather than completing a compound.
FUNCTION_WORDS = {
    "can", "will", "has", "have", "had", "may", "must", "would", "should", "is", "are", "was",
    "were", "be", "of", "to", "in", "on", "at", "by", "for", "from", "with", "and", "or",
    "that", "who", "the", "a", "an", "not", "it", "they", "he", "she", "we", "you", "as", "if",
    "but", "so", "do", "does",
}

# Chinese particles, verbs and pronouns that follow 人 without forming a compound.
CHINESE_PARTICLES = set("的得地了是在和与也都就而等很有不我他们这那一个着过吗呢吧啊")


def _is_word(text):
    """True if the token has a letter or digit (not punctuation, space or a newline)."""
    return any(unicodedata.category(ch)[0] in "LN" for ch in text)


def _is_cjk(text):
    return len(text) == 1 and "一" <= text <= "鿿"


def step(carry, prefix, upstream):
    """This token's activation, from the previous token and this token alone."""
    if len(prefix.token_strings) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    prev = prefix.token_strings[-2].strip().lower()
    cur = prefix.token_strings[-1].strip().lower()
    if prev.endswith("人"):
        # 人 + a Chinese character that can complete a noun (人气, 人类, 人妻 ...)
        if _is_cjk(cur) and cur not in CHINESE_PARTICLES:
            return None, 0.8
        return None, 0.0
    if not _is_word(cur) or cur in FUNCTION_WORDS:
        return None, 0.0
    return None, PRIMING.get(prev, 0.0)

