        elif token == 'BS':
            value = -2.15
        else:
            value = -1.2 if bare == 'BS' else -1.5
    elif word == 'obs':
        value = -0.7 if token.startswith(('.', '(')) else -1.8
    elif word.startswith(('observer', 'observable')):
