    elif word.startswith(('abdom', 'abrupt')):
        value = -0.8
    elif word in {'abortion', 'abortions'}:
        value = -0.5
    elif word in {'intensity', 'magn', 'magnitude'}:
        value = -0.3
    elif word.endswith('notfoundexception'):
        value = -1.2 if previous.strip().lower() == 'resource' else -0.4
    elif word in {'accessible', 'inaccessible'}:
        value = -0.45 if word == 'accessible' else -0.9
    elif word in {'без', 'bez', 'почти'}:
        value = -0.6
    elif token == 'б':
