ABSENCE = {"absence", "absent", "absentee"}
ABSORB = {"absorb", "absorbed", "absorbs", "absorption", "吸"}
BS_PIECE = {"bs", "obs"}
ALMOST = {"almost", "几乎", "почти", "简直"}


