"""Delimiter pulses: mostly negative, strongest on corner quotes and message ends.

Predict from visible quotation, code/math markup, and divider characters, leaving
ordinary text at zero. First occurrences of quotation/code delimiters are stronger
than repetitions. Remember their counts and the preceding token within each document.
This describes the large pulses, not the smaller, word-specific fluctuations.
"""
import math

READS = ()

MARKERS = {
    '<tool_call>': -1.215,
    '</tool_call>': -0.226,
    '</tool_response>': 0.17,
    '</think>': -0.373,
    '<think>': -0.08,
}
# Absolute response = repeated-use floor + first-use extra / (1 + count).
# The final number is the response when a quote shares its token with other text.
QUOTATION_FORMS = {
    '「': (2.90, 1.00, -2.43),
    '」': (1.80, 0.86, -1.25),
    '『': (1.90, 0.97, -1.80),
    '』': (1.13, 0.50, -0.90),
    '【': (0.51, 0.30, -0.50),
    '】': (0.08, 0.12, -0.15),
}
COUNTED_MARKS = '`「」『』«»【】'


def token_value(s, previous, position, counts):
    z = s.strip()
    spaced = s.startswith(' ')
    if s == '<|im_end|>':
        return -1.98 + 1.0 / (1 + position / 3)
    if s in MARKERS:
        return MARKERS[s]
    if not z:
        return 0.0
    if '「' in z and '」' in z:
        return -1.70
    for mark, (floor, extra, combined) in QUOTATION_FORMS.items():
        if mark in z:
            if z != mark:
                return combined
            if mark == '」' and not counts.get('「', 0) and not counts.get('」', 0):
                return -3.60
            return -floor - extra / (1 + counts.get(mark, 0))
    if '«' in z or '»' in z:
        if z not in ('«', '»'):
            return -0.45
        floor = -0.64 if spaced else (-0.40 if z == '«' else -0.33)
        return floor - 0.40 / (1 + counts.get(z, 0))
    if '・' in z:
        return -0.73 if z == '・' else -0.30
    if z == '··':
        return -0.24
    if z == "''":
        return -0.60 if spaced else -0.48
    if '`' in s:
        n = s.count('`')
        pairs = counts.get('`', 0) / 2
        if n >= 3:
            return -0.40 if spaced else -0.59
        if z == '``':
            return (-1.90 - 0.60 / (1 + pairs / 2) if spaced
                    else -1.08 - 0.68 / (1 + pairs))
        if n == 2:
            return (-2.10 if spaced else -1.26) + 0.35
        if '\n\n' in s:
            return 0.16
        if '\n' in s:
            return -0.17
        if z == '`':
            return (-0.50 - 0.36 / (1 + pairs) if spaced
                    else -0.63 - 0.30 / (1 + pairs))
        if '${' in s:
            return -1.10
        if z == '(`':
            return -0.90
        if z.startswith('`') and len(z) > 1:
            strong = z[1] == '\\' or (z[1] == '.' and spaced)
            return -0.85 if strong else -0.32
        if z.endswith('`') and z[0] in ')"':
            return -0.45
        return -0.65 if spaced else -0.72
    if z in ('$', '$$'):
        opening = spaced or not previous or previous[-1].isspace()
        if z == '$$':
            return -0.08 if opening else -0.59
        if opening:
            return 0.01
        return -0.42 if previous[-1].isalnum() else -0.27
    if z.startswith('$') and z[1:] in ('.', ',', ':'):
        return -0.18
    if z.endswith('$') and z[0] in ')}]*|.':
        return -0.34
    if all('\u2500' <= c <= '\u257f' for c in z):
        if z == '│':
            return -1.08
        if set(z) <= set('─━═'):
            return -1.3 - 0.36 * math.log2(max(1, len(z)))
        return -1.80
    if all('\u2580' <= c <= '\u259f' for c in z):
        return -0.70
    if z in ('‑', '‐'):
        return -1.55 if z == '‑' else -0.45
    if len(z) >= 4 and len(set(z)) == 1 and z[0] in '=-*#~_/.':
        n, c = len(z), z[0]
        if (c == '.' and n < 8) or (c == '#' and n < 7):
            return -0.04
        if c == '=' and n in (16, 17):
            value = -2.0 - (0.25 if spaced else 0.0)
        elif c in '=-*#':
            strength = min(1.45, max(0, 0.4 + 0.5 * math.log2(n / 4)))
            if n > 32:
                strength -= 0.28 * math.log2(n / 32)
            value = -strength
        elif c in '_~':
            value = -min(1.05, 0.30 + 0.28 * math.log2(n / 4))
        elif c == '/':
            value = -min(1.15, 0.30 + 0.35 * math.log2(n / 4))
        else:
            value = -0.55
        return value + (0.22 if '\n' in s else 0.0)
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position, counts = '', 0, {}
    else:
        _, previous, position, counts = carry
    token = prefix.token_strings[-1]
    value = token_value(token, previous, position, counts)
    for mark in COUNTED_MARKS:
        if mark in token:
            counts[mark] = counts.get(mark, 0) + token.count(mark)
    return (doc, token, position + 1, counts), float(value)

