"""Comma detector for layer-0 MLP neuron 3579 (down_proj, component 3579).

The component reads "this token is a comma-like separator" and writes it into the
residual stream. It fires on the separators that join list items, names and
appositives: ASCII ",", the full-width "，", the Chinese enumeration comma "、" and ")，".

How strongly it fires depends on the word just before the comma:
- after a transition word that opens a clause ("However,", "Moreover,", "for example,",
  "that,", "said,") it goes negative, the sign flips because the comma closes an aside;
- after a capitalised word (a name, "Yes,", "Today,") an ASCII comma is strongest;
- after an ordinary lowercase word or a number, an ASCII comma is weakly positive;
- full-width commas are strong (about 0.4) wherever they occur.
Every other token predicts 0. The word before is read only if it is in the same document.
"""

TRANSITIONS = {
    "however", "moreover", "furthermore", "therefore", "thus", "alternatively",
    "similarly", "example", "instance", "particular", "then", "now", "case", "said",
    "that", "hence", "consequently", "indeed", "instead", "nevertheless",
}
# Typical activation of each separator when no transition word comes before it.
SEPARATOR_LEVEL = {",": 0.11, "，": 0.39, "、": 0.11, ")，": 0.33}
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token not in SEPARATOR_LEVEL:
        return carry, 0.0
    word = ""
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    if same_doc:
        word = prefix.token_strings[-2].strip()
    if word.lower() in TRANSITIONS:
        return carry, -0.25
    if token == "," and word[:1].isupper():
        return carry, 0.22
    return carry, SEPARATOR_LEVEL[token]

