programs.sol:
"""A whitespace-layout response, with a weaker number-to-text boundary response.

Short runs of spaces just after a newline are negative (especially one space).
Mid-line alignment spaces, nonbreaking spaces, and tab-plus-space separators
are positive. Tabs after numbers, as in numbered source listings, are strongest.
The constants calibrate whitespace widths, not token identities. Ordinary text
is near zero, except space-prefixed capitals immediately after a number.
"""
READS = ()


def spaces(width, line_start):
    if width >= 64:
        return -0.15
    if line_start:
        if width == 1:
            return -1.40
        if width <= 3:
            return -0.44
        if width == 4:
            return -0.55
        if width <= 6:
            return 0.17
        if width % 4 == 3:
            return 0.01
        return -0.22 if width % 4 == 0 else 0.30
    if width == 1:
        return 0.01
    if width == 2:
        return 0.71
    if width <= 4:
        return 0.47
    if width <= 6:
        return 1.02
    if width <= 10:
        return 0.72 if width <= 8 else 0.95
    return 0.75 if width % 4 == 1 else 0.50


def tab_spaces(width):
    if width <= 3:
        return 2.45
    if width == 4:
        return 2.14
    if width in (5, 9):
        return 3.25 - 0.07 * width
    if width >= 11:
        return max(1.0, 2.66 - 0.04 * width)
    return 2.40 - 0.036 * width


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    number = bool(previous) and previous[-1].isdigit()
    newline = previous.endswith('\n')
    value = 0.0

    if token and set(token) == {' '}:
        width = len(token)
        value = spaces(width, newline)
        if not previous and width == 1:
            value = 0.15
        elif number and width > 1:
            value += 0.35
        elif previous.endswith('\\n'):
            value = -0.39 if width == 1 else value - 0.35
        elif newline and '\t' in previous and width <= 4:
            value += 0.20
        elif previous.isspace() and not newline:
            value *= 0.5
    elif token and set(token) == {'\xa0'}:
        value = 1.25 if number else 0.90
        if not number and (newline or previous.isspace()):
            value = 0.56
    elif token.startswith('\t'):
        width = token.count(' ')
        if token.isspace() and width:
            value = tab_spaces(width)
            if '\n' in token:
                value *= 0.40
            elif not number:
                if newline:
                    value -= 1.15
                elif not previous:
                    value -= 1.30
                else:
                    value -= 0.90 if previous.isspace() else 0.25
        elif token.isspace():
            if number:
                value = max(0.8, 1.36 - 0.075 * (token.count('\t') - 1))
                if '\n' in token:
                    value = 0.47
            elif previous and not newline and not previous.isspace():
                value = 0.90
            else:
                value = -0.08
        elif number:
            value = 0.65
    elif number and token.startswith(' '):
        first = token.lstrip()[:1]
        value = 0.36 if first.isupper() else 0.04
        if token.strip() == '|':
            value = 0.20
    elif token == '\ufffd':
        # Some byte-fragment tokens finish a multibyte Unicode space.
        if prefix.text_prefixes[-1][-1].isspace():
            value = 0.65

    return (doc, token), float(value)

