"""A current-token detector for written DOWN / LOWER cues, not sentence meaning.

The Chinese character 下 gives the strongest negative response, even inside
words where its meaning has shifted. A few short combinations remain strong;
other compounds are attenuated by their length and character position.
English lower/down words, 'following', the Korean syllable 하, and arrows are
weaker cues. Upper-position forms also receive a smaller negative response.
"""
READS = ()

SHORT_DOWN_FORMS = {'一下', '天下', '之下', '下的', '下了', '下一'}
CONVENTIONAL_DOWN_WORDS = {'下载', '下載', '下降', '下跌', '下去', '下午'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip()
    if text == '下':
        value = -8.0
    elif '下' in text:
        if text in SHORT_DOWN_FORMS:
            value = -6.2
        elif text in CONVENTIONAL_DOWN_WORDS:
            value = -2.1
        elif text == '以下':
            value = -3.35
        elif text == '下さい':
            value = -0.6
        else:
            value = -5.0 if text.endswith('下') else -3.5
            if len(text) > 2:
                value *= 0.65
    elif '上' in text:
        value = -1.5 if text == '上' else -0.9
    elif text == '하':
        value = -4.0 if token.startswith(' ') else -4.8
    elif text in {'상', '↓'}:
        value = -0.9
    elif text == 'ダウン':
        value = -1.6
    else:
        word = text.strip('._-/')
        capitalized = word[0:1].isupper()
        word = word.lower()
        value = 0.0
        if word in {'down', 'below', 'lower'}:
            value = {'down': -1.35, 'below': -1.8, 'lower': -1.85}[word]
            value -= 0.3 * capitalized
        elif word in {'lowercase', 'tolower', 'tolowercase'}:
            value = -1.85
        elif word.startswith('down') or word in {
            'lowered', 'lowering', 'lowers'
        }:
            value = -1.3
        elif word == 'following':
            value = -0.83 - 0.15 * capitalized
        elif word in {'bottom', 'bottoms'}:
            value = -0.83
        elif word in {
            'upper', 'uppercase', 'lowest', 'underneath', 'beneath', 'fallen'
        }:
            value = -0.55
        elif word.startswith('descend'):
            value = -0.6
        elif word == 'low':
            value = -0.33
        elif text in {'低', '降低', '降', '落', '底'}:
            value = -0.85
    return None, value

programs.haiku:
"""Layer-0 MLP down_proj component 3583: a token detector.

It is strongly negative (about -1.5) on the adverb "nearly" (and "Nearly"), which
precedes a quantity ("nearly half", "nearly 5 years"), and on the Chinese conditional
"若" / "若是" ("if"). It is moderately positive (about +0.7) on "underlying"
(as in "the underlying mechanism"). Everywhere else it is near 0.
"""

READS = ()

NEARLY = {"nearly"}
IF_WORDS = {"若", "若是"}
UNDERLYING = {"underlying"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in NEARLY:
        value = -1.5
    elif word in IF_WORDS:
        value = -1.3
    elif word in UNDERLYING:
        value = 0.7
    else:
        value = 0.0
    return carry, value
